    // ================================================================
    // DEFAULT SETTINGS
    // ================================================================

    var DEFAULT_COLORS = {
        fhn: '#e53935', bhn: '#1e88e5', fhd: '#ff9800', bhd: '#43a047',
        onsite: '#2e7d32', offsite: '#c62828', fclmButton: '#ff9900',
        flexBadge: '#9c27b0', laborTrack: '#00C853'
    };

    var DEFAULT_THEME = {
        enabled: false, background: '#1a1a2e', cardBackground: '#16213e',
        headerBackground: '#0f3460', textColor: '#e8e8e8',
        accentColor: '#ff9900', borderColor: '#2a2a4a'
    };

    var DEFAULT_SETTINGS = {
        siteCode: '', scopeId: null,
        onboardingComplete: false,
        showIncidentShiftCodes: true, showFCLMButtons: true, showIcareButton: true,
        showClockStatus: true, showShiftCodeBadges: true,
        showFlexDropdown: true, showTodayShiftBanner: true,
        showTerminatedBadge: true, showPathTooltip: true,
        showLaborTracking: true, showMedicalAlert: true,
        showFollowUps: true, showICare: true, showRegulatory: true,
        showBodyParts: true, showLocation: true,
        showDiagnosis: true, showProcessPath: true, showImpactType: true,
        caseDetailsDefaultCollapsed: true,
        // Side-panel visibility flags. Every toolbar panel can be hidden
        // independently from the settings panel. All default ON.
        showRBITracker: true,
        showSIMBATracker: true,
        showAnalyticsPanel: true,
        showPinPanel: true,
        showRTWPanel: true,
        showAmcarePanel: true,
        showRotationsPanel: true,
        showSitePersonnelPanel: true,
        showHuddlePanel: true,
        showSlackBotPanel: true,
        showDragonflyPanel: true,
        showEventAnalytics: false,      // Beta — hidden by default until GA
        showGuidePanel: true,           // 📖 in-app tutorials — default ON
        showOnsiteCheckPanel: true,     // 🔍 bulk on-site status lookup (FCLM + Rally Point)
        showAnalyticsHeatmaps: true,
        showAnalyticsProcessPath: true,
        showAnalyticsPredictive: true,
        showAnalyticsClaimFiled: true,
        showAnalyticsRecordablesDeepDive: true,
        showAnalyticsManagerSection: true,
        showAnalyticsRiskForecast: false, // WORK IN PROGRESS — off by default
        showAnalyticsRiskClassifier: true,
        showAnalyticsRiskWatch: true,
        showAnalyticsRiskClusters: true,
        shiftSummaryChannelId: '',
        hoursSource: 'auto',  // 'auto' | 'appsync' | 'drive'
        rbiDateRangeMode: 'thisWeek',   // 'thisWeek' | 'lastWeek' | 'custom'
        rbiCustomStartDate: null,        // YYYY-MM-DD (only used when mode='custom')
        rbiCustomEndDate: null,          // YYYY-MM-DD
        showPriorYearCases: false,
        showRotations: true,
        // When true, FCLM clock fetches use the PPA timeDetails endpoint
        // (ppaTimeDetails?employeeId=...&warehouseId=<site>) instead of the
        // regular timeDetails endpoint. AIR (Amazon Air Hub) sites need this
        // to surface clock status correctly.
        airSiteFclm: false,
        showCommandDashboard: false, // WORK IN PROGRESS — off by default
        darkOverlay: false,
        colors: assign({}, DEFAULT_COLORS),
        theme: assign({}, DEFAULT_THEME)
    };

    var THEME_PRESETS = {
        dark:     { name: 'Dark',     background: '#1a1a2e', cardBackground: '#16213e', headerBackground: '#0f3460', textColor: '#e8e8e8', accentColor: '#ff9900', borderColor: '#2a2a4a' },
        midnight: { name: 'Midnight', background: '#0d1117', cardBackground: '#161b22', headerBackground: '#21262d', textColor: '#c9d1d9', accentColor: '#58a6ff', borderColor: '#30363d' },
        forest:   { name: 'Forest',   background: '#1a2f1a', cardBackground: '#243524', headerBackground: '#2d4a2d', textColor: '#d4e6d4', accentColor: '#7cb342', borderColor: '#3d5c3d' },
        ocean:    { name: 'Ocean',    background: '#0a1929', cardBackground: '#0d2137', headerBackground: '#1a3a5c', textColor: '#b2d4f5', accentColor: '#29b6f6', borderColor: '#1e4976' }
    };

    // ================================================================
