    // ================================================================
    // AUTH TOKEN WITH FAILURE TRACKING
    // ================================================================

    function getAuthToken() {
        var authState = lib.authState;

        if (state._cachedAuthToken && (Date.now() - state._cachedAuthTokenTime) < 300000) {
            authState.status = 'ok';
            return state._cachedAuthToken;
        }

        function _win(key, val) {
            state._cachedAuthToken = val;
            state._cachedAuthTokenTime = Date.now();
            state._cachedAuthTokenKey = key;
            authState.status = 'ok';
            authState.failCount = 0;
            authState.notified = false;
            authState.lastCheck = Date.now();
            return val;
        }

        // Fast path: previous scan told us which localStorage key held
        // the token — check it first before re-walking every key.
        if (state._cachedAuthTokenKey) {
            var quick = localStorage.getItem(state._cachedAuthTokenKey);
            if (quick && quick.startsWith('eyJ') && quick.length > 500) {
                return _win(state._cachedAuthTokenKey, quick);
            }
            // Key rotated — invalidate and re-scan below.
            state._cachedAuthTokenKey = null;
        }

        // Single-pass scan (was two separate loops). Prefer any key
        // containing `.accessToken`; fall back to any JWT-shaped value
        // that isn't a refresh token.
        var fallback = null, fallbackKey = null;
        for (var i = 0; i < localStorage.length; i++) {
            var k = localStorage.key(i);
            if (!k) continue;
            var v = localStorage.getItem(k);
            if (!v || v.length < 500 || !v.startsWith('eyJ')) continue;
            if (k.indexOf('.accessToken') !== -1) {
                return _win(k, v);
            }
            if (!fallback && k.indexOf('.refreshToken') === -1) {
                fallback = v; fallbackKey = k;
            }
        }
        if (fallback) return _win(fallbackKey, fallback);

        // Token not found
        authState.status = 'failed';
        authState.failCount++;
        authState.lastCheck = Date.now();

        if (authState.failCount >= 3 && !authState.notified) {
            authState.notified = true;
            showAuthBanner();
        }

        return null;
    }

