    // ================================================================
    // SCOPE ID DISCOVERY
    // ================================================================

    function getScopeId() {
        var s = state.settings;
        var discoveredScope = null;

        var searchKeys = [
            'austin_core_global_search_filters.IncidentsDashboard',
            'austin_core_global_search_filters.HoursWorkedDashboard',
            'austin_core_global_search_filters.home-task-search',
            'austin_core_global_search_filters.home-calendar',
            'austin_core_global_search_filters.ComplianceActivitiesDashboard'
        ];

        for (var i = 0; i < searchKeys.length; i++) {
            try {
                var v = localStorage.getItem(searchKeys[i]);
                if (!v) continue;
                var p = JSON.parse(v);
                var sv = p.Site || p.site;
                if (sv && sv.indexOf('TDA|') === 0) {
                    discoveredScope = sv;
                    break;
                }
                if (p.filterValues && p.filterValues.site) {
                    sv = p.filterValues.site;
                    if (sv && sv.indexOf('TDA|') === 0) {
                        discoveredScope = sv;
                        break;
                    }
                }
            } catch (e) {}
        }

        if (!discoveredScope) {
            for (var j = 0; j < localStorage.length; j++) {
                try {
                    var k = localStorage.key(j);
                    var val = localStorage.getItem(k);
                    if (val && val.indexOf('TDA|') !== -1) {
                        var m = val.match(/TDA\|[a-f0-9-]{36}/);
                        if (m) {
                            discoveredScope = m[0];
                            break;
                        }
                    }
                } catch (e) {}
            }
        }

        if (discoveredScope) {
            if (s.scopeId && s.scopeId !== discoveredScope) {
                console.log('WHSLib: Scope ID changed');
                state.bulkCaseData.clear();
                state.bulkMinimalData.clear();
                state.bulkDataTimestamp = 0;
                state.bulkDataLoading = false;
                state.bulkDataPromise = null;
            }
            s.scopeId = discoveredScope;
            saveSettings(s);
            return discoveredScope;
        }

        return s.scopeId || null;
    }

    // ================================================================
