    function detectSiteCode() {
        var chipEl = document.querySelector('.MuiChip-label.MuiChip-labelMedium');
        if (chipEl && chipEl.textContent && chipEl.textContent !== 'Regional') {
            return chipEl.textContent.trim();
        }

        var headingEl = document.querySelector('h1.MuiTypography-h1');
        if (headingEl) {
            var hm = headingEl.textContent.match(/\d{1,2}\/\d{1,2}\/\d{4}\s+-\s+#([^-]+)/);
            if (hm) return hm[1].trim();
        }

        var titleEl = document.querySelector('h1[data-testid="IncidentBasicInfo-title"]');
        if (titleEl) {
            var tm = titleEl.textContent.match(/#([^-]+)-/);
            if (tm) return tm[1].trim();
        }

        return null;
    }

