    // ================================================================
    // PANEL SHELL
    // ================================================================
    function createAnalyticsPanel() {
        var ex = document.getElementById('whs-analytics-panel'); if (ex) ex.remove();
        var exb = document.getElementById('whs-analytics-toggle'); if (exb) exb.remove();

        // Floating toggle removed — now controlled from toolbar button

        var panel = document.createElement('div');
        panel.id = 'whs-analytics-panel';

        var header = document.createElement('div');
        header.className = 'wa-header';
        header.innerHTML =
            '<div class="wa-header-row"><div>' +
            '<div class="wa-header-title">\uD83D\uDCCA Site Analytics</div>' +
            '<div class="wa-header-subtitle" id="wa-header-sub">Select a month to begin</div>' +
            '</div><div style="display:flex;gap:6px;align-items:center;">' +
            '<button class="wa-export-btn" id="wa-shift-summary-btn" title="Compose and post a shift injury trends summary to Slack" style="background:linear-gradient(135deg,#4a154b,#611f69);border-color:#611f69;">📨 Shift Summary</button>' +
            '<button class="wa-export-btn" id="wa-export-btn" title="Export to Excel">\uD83D\uDCCA Export</button>' +
            '<button class="wa-fullscreen-btn" id="wa-fullscreen-btn" title="Toggle fullscreen">\u26F6</button>' +
            '<button id="wa-close-btn" style="background:none;border:none;color:#666;font-size:18px;cursor:pointer;padding:0 4px;line-height:1;" title="Close">\u2715</button>' +
            '</div></div><div class="wa-filters" id="wa-filters"></div>';
        panel.appendChild(header);

        var content = document.createElement('div');
        content.className = 'wa-content';
        content.id = 'wa-content';
        content.innerHTML = '<div class="wa-loading"><div class="wa-loading-spinner"></div><br>Waiting for data...</div>';
        panel.appendChild(content);

        var footer = document.createElement('div');
        footer.className = 'wa-footer';
        footer.id = 'wa-footer';
        footer.textContent = 'Click any bar to see contributing cases';
        panel.appendChild(footer);
        document.body.appendChild(panel);

        document.getElementById('wa-close-btn').addEventListener('click', function () { togglePanel(false); });
        document.getElementById('wa-export-btn').addEventListener('click', function () { exportToExcel(); });
        var ssBtn = document.getElementById('wa-shift-summary-btn');
        if (ssBtn) ssBtn.addEventListener('click', function () { openShiftSummaryModal(); });
        document.getElementById('wa-fullscreen-btn').addEventListener('click', function (e) {
            e.stopPropagation();
            toggleFullscreen();
        });
        buildFilterBar();
    }

    function toggleFullscreen(forceState) {
        var panel = document.getElementById('whs-analytics-panel');
        var toggle = document.getElementById('whs-analytics-toggle');
        var fsBtn = document.getElementById('wa-fullscreen-btn');
        if (!panel) return;
        A.isFullscreen = typeof forceState === 'boolean' ? forceState : !A.isFullscreen;
        if (A.isFullscreen) {
            panel.classList.add('fullscreen');
            if (toggle) toggle.classList.add('panel-fullscreen');
            if (fsBtn) { fsBtn.classList.add('active'); fsBtn.textContent = '\u2716'; }
        } else {
            panel.classList.remove('fullscreen');
            if (toggle) { toggle.classList.remove('panel-fullscreen'); toggle.classList.add('panel-open'); }
            if (fsBtn) { fsBtn.classList.remove('active'); fsBtn.textContent = '\u26F6'; }
        }
    }

    function getPeriodLabel(short) {
        if (currentFilters.dateFrom && currentFilters.dateTo) {
            var fmt = function (iso) {
                var d = new Date(iso);
                return (short ? MONTH_SHORT : MONTH_NAMES)[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
            };
            return fmt(currentFilters.dateFrom) + ' \u2013 ' + fmt(currentFilters.dateTo);
        }
        if (short) {
            return currentFilters.month === 'all' ? 'All ' + currentFilters.year : MONTH_SHORT[currentFilters.month] + ' ' + currentFilters.year;
        }
        return currentFilters.month === 'all' ? 'All of ' + currentFilters.year : MONTH_NAMES[currentFilters.month] + ' ' + currentFilters.year;
    }

    function buildFilterBar() {
        var container = document.getElementById('wa-filters');
        if (!container) return;
        container.innerHTML = '';
        var thisYear = new Date().getFullYear();
        var isRange = !!(currentFilters.dateFrom && currentFilters.dateTo);

        // Row 1 — Year / All Months (hidden when range active)
        if (!isRange) {
            var row1 = document.createElement('div'); row1.className = 'wa-filter-row';
            var yearLabel = document.createElement('span'); yearLabel.className = 'wa-filter-label'; yearLabel.textContent = 'Period';
            row1.appendChild(yearLabel);
            [thisYear - 1, thisYear].forEach(function (yr) {
                var btn = document.createElement('button');
                btn.className = 'wa-filter-btn' + (currentFilters.year === yr ? ' active' : '');
                btn.textContent = yr;
                btn.addEventListener('click', function (e) { e.stopPropagation(); currentFilters.year = yr; buildFilterBar(); A.debouncedRefresh(); });
                row1.appendChild(btn);
            });
            var sp1 = document.createElement('div'); sp1.style.cssText = 'width:1px;height:16px;background:#21262d;margin:0 2px;';
            row1.appendChild(sp1);
            var allBtn = document.createElement('button');
            allBtn.className = 'wa-filter-btn' + (currentFilters.month === 'all' ? ' active' : '');
            allBtn.textContent = 'All Months';
            allBtn.addEventListener('click', function (e) { e.stopPropagation(); currentFilters.month = 'all'; buildFilterBar(); A.debouncedRefresh(); });
            row1.appendChild(allBtn);
            container.appendChild(row1);

            // Row 2 — Months
            var row2 = document.createElement('div'); row2.className = 'wa-filter-row';
            var monthLabel = document.createElement('span'); monthLabel.className = 'wa-filter-label'; monthLabel.textContent = 'Month';
            row2.appendChild(monthLabel);
            for (var m = 0; m < 12; m++) {
                (function (month) {
                    var btn = document.createElement('button');
                    btn.className = 'wa-filter-btn' + (currentFilters.month === month ? ' active' : '');
                    btn.textContent = MONTH_SHORT[month];
                    btn.addEventListener('click', function (e) { e.stopPropagation(); currentFilters.month = month; buildFilterBar(); A.debouncedRefresh(); });
                    row2.appendChild(btn);
                })(m);
            }
            container.appendChild(row2);
        }

        // Row 3 — Shift
        var row3 = document.createElement('div'); row3.className = 'wa-filter-row';
        var shiftLabel = document.createElement('span'); shiftLabel.className = 'wa-filter-label'; shiftLabel.textContent = 'Shift';
        row3.appendChild(shiftLabel);
        ['all', 'FHD', 'FHN', 'BHD', 'BHN'].forEach(function (sk) {
            var btn = document.createElement('button');
            btn.className = 'wa-filter-btn' + (currentFilters.shift === sk ? ' active' : '');
            btn.textContent = sk === 'all' ? 'All Shifts' : sk;
            btn.addEventListener('click', function (e) { e.stopPropagation(); currentFilters.shift = sk; buildFilterBar(); A.debouncedRefresh(); });
            row3.appendChild(btn);
        });
        container.appendChild(row3);

        // Row 4 — Custom Date Range
        var row4 = document.createElement('div'); row4.className = 'wa-filter-row';
        var rangeLabel = document.createElement('span'); rangeLabel.className = 'wa-filter-label'; rangeLabel.textContent = 'Range';
        row4.appendChild(rangeLabel);

        var rangeToggle = document.createElement('button');
        rangeToggle.className = 'wa-filter-btn' + (isRange ? ' active' : '');
        rangeToggle.textContent = isRange ? '\u2715 Clear Range' : '\uD83D\uDCC5 Custom Range';
        rangeToggle.title = isRange ? 'Clear custom date range' : 'Set a custom date range';
        rangeToggle.addEventListener('click', function (e) {
            e.stopPropagation();
            if (isRange) {
                currentFilters.dateFrom = null;
                currentFilters.dateTo = null;
            } else {
                // Default to current year Jan 1 → today
                var now = new Date();
                var y = now.getFullYear();
                currentFilters.dateFrom = y + '-01-01';
                currentFilters.dateTo = now.toISOString().slice(0, 10);
            }
            buildFilterBar();
            A.debouncedRefresh();
        });
        row4.appendChild(rangeToggle);

        if (isRange) {
            var fromLabel = document.createElement('span');
            fromLabel.textContent = 'From';
            fromLabel.className = 'wa-filter-label';
            fromLabel.style.cssText = 'margin-left:8px;min-width:unset;';
            row4.appendChild(fromLabel);

            var fromInput = document.createElement('input');
            fromInput.type = 'date';
            fromInput.className = 'wa-date-input';
            fromInput.value = currentFilters.dateFrom || '';
            fromInput.addEventListener('change', function (e) {
                e.stopPropagation();
                currentFilters.dateFrom = this.value;
                if (currentFilters.dateFrom && currentFilters.dateTo) A.debouncedRefresh();
            });
            row4.appendChild(fromInput);

            var toLabel = document.createElement('span');
            toLabel.textContent = 'To';
            toLabel.className = 'wa-filter-label';
            toLabel.style.cssText = 'margin-left:6px;min-width:unset;';
            row4.appendChild(toLabel);

            var toInput = document.createElement('input');
            toInput.type = 'date';
            toInput.className = 'wa-date-input';
            toInput.value = currentFilters.dateTo || '';
            toInput.addEventListener('change', function (e) {
                e.stopPropagation();
                currentFilters.dateTo = this.value;
                if (currentFilters.dateFrom && currentFilters.dateTo) A.debouncedRefresh();
            });
            row4.appendChild(toInput);
        }

        container.appendChild(row4);
    }

    function togglePanel(forceState) {
        var panel = document.getElementById('whs-analytics-panel');
        var toggle = document.getElementById('whs-analytics-toggle');
        if (!panel) return;
        A.panelOpen = typeof forceState === 'boolean' ? forceState : !A.panelOpen;
        if (A.panelOpen) {
            panel.classList.add('open');
            if (toggle) toggle.classList.add('panel-open');
            refreshAnalytics();
        } else {
            panel.classList.remove('open');
            if (toggle) toggle.classList.remove('panel-open');
            if (A.isFullscreen) toggleFullscreen(false);
        }
    }

    // ================================================================
    // SECTION BUILDERS (compact — same logic as original)
    // ================================================================
    function buildDrilldownTable(cases, groupKey, groupValue, extraColumns) {
        var id = 'dd-' + groupKey + '-' + groupValue.replace(/[^a-zA-Z0-9]/g, '_');
        var html = '<div class="wa-drilldown" id="' + id + '"><div class="wa-drilldown-header"><span><strong>' + cases.length + '</strong> cases \u2014 ' + escapeHtml(formatLabel(groupValue)) + '</span><span class="wa-source-tag">grouped by: ' + escapeHtml(groupKey) + '</span></div><div class="wa-drilldown-scroll"><table class="wa-drilldown-table"><thead><tr><th>Case #</th><th>Date</th><th>Shift</th><th>Associate</th>';
        if (extraColumns) { for (var h = 0; h < extraColumns.length; h++) html += '<th>' + escapeHtml(extraColumns[h].header) + '</th>'; }
        html += '<th>Status</th></tr></thead><tbody>';
        for (var i = 0; i < cases.length; i++) {
            var c = cases[i]; var sk = c._calcShiftCode || 'UNK'; var shiftColor = PALETTE.shift[sk] || '#555';
            var caseUrl = buildIncidentUrl(c);
            html += '<tr>';
            html += caseUrl ? '<td><a class="wa-case-link" href="' + caseUrl + '" target="_blank">' + escapeHtml(c.caseNumber || '\u2014') + '</a></td>' : '<td>' + escapeHtml(c.caseNumber || '\u2014') + '</td>';
            html += '<td>' + formatDateTime(c.incidentDateTime) + '</td>';
            html += '<td><span class="wa-shift-pill" style="background:' + shiftColor + '22;color:' + shiftColor + ';border:1px solid ' + shiftColor + '44;">' + sk + '</span></td>';
            html += '<td>' + escapeHtml(c.alias || '\u2014') + '</td>';
            if (extraColumns) { for (var ec = 0; ec < extraColumns.length; ec++) html += '<td>' + escapeHtml(extraColumns[ec].getValue(c) || '\u2014') + '</td>'; }
            var stColor = c.status === 'IN_PROGRESS' ? '#64b5f6' : c.status === 'CLOSED' ? '#81c784' : c.status === 'FOR_REVIEW' ? '#ffb74d' : '#888';
            html += '<td style="color:' + stColor + ';">' + escapeHtml(c.status || '\u2014') + '</td></tr>';
        }
        html += '</tbody></table></div></div>';
        return html;
    }

    function buildBarChartWithDrilldown(ranked, total, casesMap, groupKey, options) {
        var opts = options || {};
        var maxBars = opts.maxBars || 15; var colors = opts.colors || PALETTE.bodyPart;
        var colorMap = opts.colorMap || null; var labelWidth = opts.labelWidth || '120px';
        var extraColumns = opts.extraColumns || null; var prevCounts = opts.prevCounts || null;
        if (!ranked || ranked.length === 0) return '<div class="wa-empty">No data available</div>';
        var maxCount = ranked[0].count; var html = ''; var display = ranked.slice(0, maxBars);
        display.forEach(function (item, idx) {
            var barPct = maxCount > 0 ? Math.round((item.count / maxCount) * 100) : 0;
            var fillColor = colorMap ? (colorMap[item.key] || colors[idx % colors.length]) : colors[idx % colors.length];
            var ddId = 'dd-' + groupKey + '-' + item.key.replace(/[^a-zA-Z0-9]/g, '_');
            var isExpanded = expandedSections[ddId] || false;
            html += '<div class="wa-bar-row" data-dd-id="' + ddId + '" data-dd-group="' + escapeHtml(groupKey) + '" data-dd-value="' + escapeHtml(item.key) + '">';
            html += '<div class="wa-bar-label" style="min-width:' + labelWidth + ';max-width:' + labelWidth + ';" title="' + escapeHtml(formatLabel(item.key)) + '">' + escapeHtml(formatLabel(item.key)) + '</div>';
            html += '<div class="wa-bar-track"><div class="wa-bar-fill" style="width:' + barPct + '%;background:' + fillColor + ';">' + item.count + '</div></div>';
            html += '<div class="wa-bar-count">' + pct(item.count, total);
            if (prevCounts) { var prevVal = prevCounts[item.key] || 0; var mom = momChange(item.count, prevVal); var momClass = mom.arrow === '\u2191' ? 'wa-mom-up' : mom.arrow === '\u2193' ? 'wa-mom-down' : 'wa-mom-flat'; html += '<span class="wa-mom ' + momClass + '">' + mom.arrow + ' ' + mom.label + '</span>'; }
            html += '</div><div class="wa-bar-expand ' + (isExpanded ? 'open' : '') + '">\u25B6</div></div>';
            if (isExpanded && casesMap[item.key]) html += buildDrilldownTable(casesMap[item.key], groupKey, item.key, extraColumns);
        });
        if (ranked.length > maxBars) { var remaining = ranked.length - maxBars; var rc = 0; for (var i = maxBars; i < ranked.length; i++) rc += ranked[i].count; html += '<div style="text-align:center;font-size:9px;color:#555;margin-top:6px;">+ ' + remaining + ' more (' + rc + ' cases)</div>'; }
        return html;
    }

    function buildSection(id, icon, title, badgeText, bodyHTML, startCollapsed) {
        var collapsed = startCollapsed ? ' collapsed' : '';
        return '<div class="wa-section' + collapsed + '" id="wa-sec-' + id + '"><div class="wa-section-header" data-wa-toggle="true"><div style="display:flex;align-items:center;gap:8px;"><span style="font-size:13px;">' + icon + '</span><span class="wa-section-title">' + title + '</span></div><div style="display:flex;align-items:center;gap:8px;">' + (badgeText ? '<span class="wa-section-badge">' + badgeText + '</span>' : '') + '<span class="wa-section-chevron">\u25BC</span></div></div><div class="wa-section-body">' + bodyHTML + '</div></div>';
    }

    function buildStatCard(value, label, sublabel, color) {
        var c = color || '#ff9900';
        return '<div class="wa-stat-card"><div class="wa-stat-value" style="color:' + c + ';">' + value + '</div><div class="wa-stat-label">' + escapeHtml(label) + '</div>' + (sublabel ? '<div class="wa-stat-sub">' + sublabel + '</div>' : '') + '</div>';
    }

    // ================================================================
    // RENDER SECTIONS (identical logic to original, condensed)
    // ================================================================
    function renderSummary(a, prevCounts) {
        var siteCode = (state.settings && state.settings.siteCode) || '';
        var periodLabel = getPeriodLabel(false);
        var shiftSuffix = currentFilters.shift !== 'all' ? ' &middot; <strong style="color:' + (PALETTE.shift[currentFilters.shift] || '#fff') + ';">' + currentFilters.shift + '</strong>' : '';
        var body = '<div style="font-size:10px;color:#888;margin-bottom:10px;">Site: <strong style="color:#ff9900;">' + escapeHtml(siteCode) + '</strong> &middot; Period: <strong style="color:#ff9900;">' + periodLabel + '</strong>' + shiftSuffix + '</div>';
        body += '<div class="wa-recordable-card"><div class="wa-recordable-value">' + a.recordableRate + '%</div><div class="wa-recordable-label">Recordable Conversion Rate</div>';
        body += '<div class="wa-recordable-sub">' + a.recordableCount + ' recordable out of ' + a.totalCases + ' total cases</div>';
        if (prevCounts && prevCounts.total > 0) { var prevRecRate = pctNum(prevCounts.recordableCount, prevCounts.total); var recMom = momChange(a.recordableRate, prevRecRate); var recMomClass = recMom.arrow === '\u2191' ? 'wa-mom-up' : recMom.arrow === '\u2193' ? 'wa-mom-down' : 'wa-mom-flat'; body += '<div style="margin-top:6px;"><span class="wa-mom ' + recMomClass + '">vs last month: ' + recMom.arrow + ' ' + recMom.label + ' (was ' + prevRecRate + '%)</span></div>'; }
        body += '</div>';
        body += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px;">';
        body += '<div class="wa-closure-card"><div class="wa-closure-value">' + a.closureRate + '%</div><div class="wa-closure-label">Closure Rate</div><div class="wa-closure-sub">' + a.closedMedicalCount + ' closed / ' + a.totalWithMedicalStatus + ' with medical status</div></div>';
        var openColor = a.openMedicalCount > 0 ? '#ffb74d' : '#81c784';
        body += '<div class="wa-stat-card" style="display:flex;flex-direction:column;justify-content:center;"><div class="wa-stat-value" style="color:' + openColor + ';">' + a.openMedicalCount + '</div><div class="wa-stat-label">Open Medical</div></div></div>';
        body += '<div class="wa-stats-grid-3">' + buildStatCard(a.totalCases, 'Total Cases', null, '#ff9900') + buildStatCard(a.recordableCount, 'Recordable', null, '#f44336') + buildStatCard(Object.keys(a.locationCounts).length, 'Locations', null, '#26a69a') + '</div>';
        return buildSection('summary', '\uD83D\uDCCB', 'Summary', a.totalCases + ' cases', body, false);
    }

    function renderTrendsSection(a) {
        var isRange = !!(currentFilters.dateFrom && currentFilters.dateTo);
        var displayYear = currentFilters.year;
        var body = '';

        if (isRange) {
            // In range mode: group the filtered cases by month+year for a simple bar trend
            var buckets = {};
            a.cases.forEach(function (c) {
                var d = new Date(c.incidentDateTime || c.reportedDateTime);
                if (isNaN(d)) return;
                var key = d.getFullYear() + '-' + (d.getMonth() + 1);
                if (!buckets[key]) buckets[key] = { total: 0, recordable: 0 };
                buckets[key].total++;
                if (c.recordable) buckets[key].recordable++;
            });
            var keys = Object.keys(buckets).sort();
            var labels = keys.map(function (k) { var parts = k.split('-'); return MONTH_SHORT[parseInt(parts[1]) - 1] + ' ' + parts[0]; });
            var totalVals = keys.map(function (k) { return buckets[k].total; });
            var recVals   = keys.map(function (k) { return buckets[k].recordable; });
            if (keys.length === 0) {
                body = '<div class="wa-empty">No data in selected range</div>';
            } else {
                body += '<div class="wa-chart-container"><div class="wa-chart-title">\uD83D\uDCC8 Total Cases vs Recordable \u2014 ' + getPeriodLabel(true) + '</div>' + buildSVGLineChart([{ name: 'Total Cases', values: totalVals, color: '#ff9900' }, { name: 'Recordable', values: recVals, color: '#f44336' }], labels, { height: 200 }) + '</div>';
            }
            return buildSection('trends', '\uD83D\uDCC8', 'Monthly Trends', getPeriodLabel(true), body, false);
        }

        var trends = computeMonthlyTrends(displayYear, currentFilters.shift);
        var currentMonth = new Date().getMonth();
        var maxMonth = displayYear < new Date().getFullYear() ? 11 : currentMonth;
        var labels = [];
        for (var mi = 0; mi <= maxMonth; mi++) labels.push(MONTH_SHORT[mi]);
        var totalVals = [], recVals = [];
        for (var t = 0; t <= maxMonth; t++) { totalVals.push(trends[t].total); recVals.push(trends[t].recordable); }
        body += '<div class="wa-chart-container"><div class="wa-chart-title">\uD83D\uDCC8 Total Cases vs Recordable \u2014 ' + displayYear + '</div>' + buildSVGLineChart([{ name: 'Total Cases', values: totalVals, color: '#ff9900' }, { name: 'Recordable', values: recVals, color: '#f44336' }], labels, { height: 200 }) + '</div>';
        if (currentFilters.shift === 'all') {
            var shiftKeys = ['FHD', 'FHN', 'BHD', 'BHN'];
            var shiftDatasets = shiftKeys.map(function (sk) { var vals = []; for (var si = 0; si <= maxMonth; si++) vals.push(trends[si].byShift[sk] || 0); return { name: sk, values: vals, color: PALETTE.shift[sk] }; });
            body += '<div class="wa-chart-container"><div class="wa-chart-title">\uD83D\uDD04 Cases per Shift \u2014 ' + displayYear + '</div>' + buildSVGLineChart(shiftDatasets, labels, { height: 200 }) + '</div>';
        }
        return buildSection('trends', '\uD83D\uDCC8', 'Monthly Trends', displayYear, body, false);
    }

    // ================================================================
    // RECORDABLES DEEP DIVE — dedicated analytics for recordable cases
    // ================================================================
    function renderRecordablesDeepDive(a, prevCounts) {
        var settings = (WHSLib.state && WHSLib.state.settings) || {};
        if (settings.showAnalyticsRecordablesDeepDive === false) return '';
        if (a.recordableCount === 0) return '';

        var recs = a.recordableCases;
        var total = a.recordableCount;

        // ── Hero KPIs ──────────────────────────────────────────────
        var prevRec = (prevCounts && prevCounts.recordableCount) || 0;
        var mom = prevRec > 0 ? momChange(total, prevRec) : { label: '', pct: 0 };
        var openRec = recs.filter(function (c) {
            var med = (c.latestMedicalStatus || '').toLowerCase();
            return med === 'open' || med === 'pending-outside-medical';
        });
        var oldestOpen = openRec.reduce(function (max, c) {
            var d = daysSinceIncident(c);
            return d > max ? d : max;
        }, 0);
        var recRate = a.recordableRate || 0;

        var kpiColor = function (val, good, bad) {
            return val >= bad ? '#f44336' : val >= good ? '#ff9800' : '#4caf50';
        };

        var body = '<div class="wa-stats-grid" style="margin-bottom:14px;">';
        body += '<div class="wa-stat-card" style="border-top:3px solid #f44336;"><div class="wa-stat-value" style="color:#f44336;">' + total + '</div><div class="wa-stat-label">Recordables</div>' +
            (mom.label ? '<div style="font-size:9px;margin-top:4px;color:' + (mom.pct > 0 ? '#f44336' : '#4caf50') + ';">' + escapeHtml(mom.label) + ' MoM</div>' : '') + '</div>';
        body += '<div class="wa-stat-card" style="border-top:3px solid ' + kpiColor(recRate, 5, 10) + ';"><div class="wa-stat-value" style="color:' + kpiColor(recRate, 5, 10) + ';">' + recRate + '%</div><div class="wa-stat-label">Recordable Conversion Rate</div><div style="font-size:9px;margin-top:4px;color:#888;">' + total + ' of ' + a.totalCases + ' cases</div></div>';
        body += '<div class="wa-stat-card" style="border-top:3px solid #ff9800;"><div class="wa-stat-value" style="color:#ff9800;">' + openRec.length + '</div><div class="wa-stat-label">Still Open</div><div style="font-size:9px;margin-top:4px;color:#888;">Oldest ' + oldestOpen + 'd</div></div>';
        body += '<div class="wa-stat-card" style="border-top:3px solid #9c27b0;"><div class="wa-stat-value" style="color:#9c27b0;">' + uniqueAssociateCount(recs) + '</div><div class="wa-stat-label">Unique Associates</div></div>';
        body += '</div>';

        // ── Weekly trend (last 12 weeks) ───────────────────────────
        var weekly = buildWeeklyRecordableTrend(a.cases, 12);
        if (weekly.labels.length > 0) {
            body += '<div class="wa-chart-container"><div class="wa-chart-title">📉 Recordables — Last 12 Weeks</div>' +
                buildSVGLineChart([
                    { name: 'Recordables', values: weekly.recordables, color: '#f44336' },
                    { name: 'Rate %',      values: weekly.rates,       color: '#ff9800' }
                ], weekly.labels, { height: 200 }) +
                '</div>';
        }

        // ── Shift breakdown with recordable rates ──────────────────
        body += '<div class="wa-sub-title" style="margin-top:14px;">Recordables by Shift</div>';
        body += '<div class="wa-stats-grid">';
        ['FHD', 'FHN', 'BHD', 'BHN'].forEach(function (sk) {
            var info = a.shiftRecordable[sk] || { total: 0, recordable: 0 };
            var rate = info.total > 0 ? Math.round((info.recordable / info.total) * 1000) / 10 : 0;
            var color = PALETTE.shift[sk];
            body += '<div class="wa-stat-card" style="border-top:3px solid ' + color + ';">' +
                '<div class="wa-stat-value" style="color:' + color + ';">' + info.recordable + '</div>' +
                '<div class="wa-stat-label">' + sk + '</div>' +
                '<div style="margin-top:4px;font-size:9px;color:' + (rate > 10 ? '#f44336' : '#888') + ';">' + rate + '% rate</div></div>';
        });
        body += '</div>';

        // ── Top process paths (by recordable count + RATE) ─────────
        var pathStats = computeRecordablesByKey(a.cases, 'incidentProcessPath', 'incidentProcessPath');
        if (pathStats.length > 0) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">Hotspot Process Paths (by recordable rate)</div>';
            body += buildRecordableRateBar(pathStats.slice(0, 8), total);
        }

        // ── Top body parts for recordables ─────────────────────────
        var bpRec = countBy(recs, 'principalBodyPart');
        var bpRanked = A.rankCounts(bpRec, 8);
        if (bpRanked.length > 0) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">Top Body Parts — Recordables Only</div>';
            body += buildSimpleBar(bpRanked, total, '#f44336');
        }

        // ── Top locations for recordables ──────────────────────────
        var locRec = countBy(recs, 'incidentLocation');
        var locRanked = A.rankCounts(locRec, 8);
        if (locRanked.length > 0) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">Top Locations — Recordables Only</div>';
            body += buildSimpleBar(locRanked, total, '#ff9800');
        }

        // ── Top diagnoses for recordables ──────────────────────────
        var dxRec = {};
        recs.forEach(function (c) {
            var d = c.diagnosisName || c.formalDiagnosis || '';
            if (d) dxRec[d] = (dxRec[d] || 0) + 1;
        });
        var dxRanked = A.rankCounts(dxRec, 6);
        if (dxRanked.length > 0) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">Top Diagnoses — Recordables Only</div>';
            body += buildSimpleBar(dxRanked, total, '#9c27b0');
        }

        // ── Day-of-week + hour-of-day heatmaps (recordables only) ──
        var recDayOfWeek = [0,0,0,0,0,0,0];
        var recHourOfDay = [];
        for (var h = 0; h < 24; h++) recHourOfDay.push(0);
        recs.forEach(function (c) {
            var dt = c.incidentDateTime || c.reportedDateTime;
            if (!dt) return;
            try {
                var d = new Date(dt);
                if (!isNaN(d)) { recDayOfWeek[d.getDay()]++; recHourOfDay[d.getHours()]++; }
            } catch (e) {}
        });
        body += '<div class="wa-heatmap-container" style="margin-top:14px;">';
        body += '<div class="wa-heatmap-title">Recordables by Day of Week</div>';
        body += '<div class="wa-heatmap-body">' + A.buildHeatmapSVG(recDayOfWeek, A.DAY_LABELS, '', '#f44336') + '</div></div>';
        body += '<div class="wa-heatmap-container">';
        body += '<div class="wa-heatmap-title">Recordables by Hour of Day</div>';
        body += '<div class="wa-heatmap-body">' + A.buildHourHeatmapSVG(recHourOfDay) + '</div></div>';

        // ── Repeat offenders (2+ recordables) ──────────────────────
        var repeatList = findRepeatRecordables(recs);
        if (repeatList.length > 0) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">Associates with Multiple Recordables (' + repeatList.length + ')</div>';
            body += '<div class="wa-drilldown-table-wrap"><table class="wa-drilldown-table">';
            body += '<thead><tr><th>Associate</th><th style="text-align:center;">Count</th><th>Recent Body Parts</th><th>Recent Locations</th></tr></thead><tbody>';
            repeatList.slice(0, 15).forEach(function (r) {
                var bps = {}; var locs = {};
                r.cases.forEach(function (c) {
                    if (c.principalBodyPart) bps[c.principalBodyPart] = true;
                    if (c.incidentLocation) locs[c.incidentLocation] = true;
                });
                body += '<tr><td style="font-weight:600;">' + escapeHtml(r.alias) + '</td>' +
                    '<td style="text-align:center;"><span style="color:#f44336;font-weight:700;">' + r.count + '</span></td>' +
                    '<td style="color:#aaa;">' + escapeHtml(Object.keys(bps).join(', ')) + '</td>' +
                    '<td style="color:#aaa;">' + escapeHtml(Object.keys(locs).join(', ')) + '</td></tr>';
            });
            body += '</tbody></table></div>';
        }

        // ── Open recordables (oldest first) ────────────────────────
        if (openRec.length > 0) {
            var oldSorted = openRec.slice().sort(function (a, b) { return daysSinceIncident(b) - daysSinceIncident(a); });
            body += '<div class="wa-sub-title" style="margin-top:14px;">Still-Open Recordables (' + openRec.length + ', oldest first)</div>';
            body += '<div class="wa-drilldown-table-wrap"><table class="wa-drilldown-table">';
            body += '<thead><tr><th>Case #</th><th>Associate</th><th>Body Part</th><th>Location</th><th style="text-align:center;">Days</th></tr></thead><tbody>';
            oldSorted.slice(0, 20).forEach(function (c) {
                var days = daysSinceIncident(c);
                var dayColor = days > 30 ? '#f44336' : days > 14 ? '#ff9800' : '#aaa';
                body += '<tr><td>' + escapeHtml(c.caseNumber || '') + '</td>' +
                    '<td>' + escapeHtml(c.alias || '') + '</td>' +
                    '<td>' + escapeHtml(c.principalBodyPart || '') + '</td>' +
                    '<td>' + escapeHtml(c.incidentLocation || '') + '</td>' +
                    '<td style="text-align:center;color:' + dayColor + ';font-weight:700;">' + days + '</td></tr>';
            });
            body += '</tbody></table></div>';
        }

        var badge = total + ' rec · ' + recRate + '%';
        return buildSection('recordables-deep', '🚨', 'Recordables Deep Dive', badge, body, false);
    }

    // ── Recordables helpers ────────────────────────────────────────
    function uniqueAssociateCount(cases) {
        var set = {};
        cases.forEach(function (c) { if (c.alias) set[c.alias] = true; });
        return Object.keys(set).length;
    }

    function countBy(cases, field) {
        var counts = {};
        cases.forEach(function (c) {
            var v = (c[field] || '').trim();
            if (!v) return;
            counts[v] = (counts[v] || 0) + 1;
        });
        return counts;
    }

    function computeRecordablesByKey(cases, keyField) {
        // Returns [{key, total, recordable, rate}] sorted by rate desc (hotspots first)
        var map = {};
        cases.forEach(function (c) {
            var v = (c[keyField] || '').trim();
            if (!v) return;
            if (!map[v]) map[v] = { key: v, total: 0, recordable: 0 };
            map[v].total++;
            if (c.recordable) map[v].recordable++;
        });
        return Object.keys(map).map(function (k) { return map[k]; })
            .filter(function (r) { return r.recordable > 0; })
            .map(function (r) { r.rate = r.total > 0 ? Math.round((r.recordable / r.total) * 1000) / 10 : 0; return r; })
            .sort(function (a, b) { return b.recordable - a.recordable || b.rate - a.rate; });
    }

    function buildRecordableRateBar(rows, grandTotal) {
        if (rows.length === 0) return '';
        var maxRec = rows[0].recordable || 1;
        var h = '<div class="wa-stats-table">';
        rows.forEach(function (r) {
            var w = Math.round((r.recordable / maxRec) * 100);
            var rateColor = r.rate > 20 ? '#f44336' : r.rate > 10 ? '#ff9800' : '#4caf50';
            h += '<div class="wa-bar-row">' +
                '<div class="wa-bar-label" style="width:160px;" title="' + escapeHtml(r.key) + '">' + escapeHtml(formatLabel(r.key)) + '</div>' +
                '<div class="wa-bar-track"><div class="wa-bar-fill" style="width:' + w + '%;background:#f44336;"></div></div>' +
                '<div class="wa-bar-value" style="width:120px;text-align:right;font-size:10px;">' +
                    '<b style="color:#f44336;">' + r.recordable + '</b> / ' + r.total + ' ' +
                    '<span style="color:' + rateColor + ';font-weight:700;">(' + r.rate + '%)</span>' +
                '</div></div>';
        });
        h += '</div>';
        return h;
    }

    function buildSimpleBar(ranked, total, color) {
        if (ranked.length === 0) return '';
        var max = ranked[0].count || 1;
        var h = '<div class="wa-stats-table">';
        ranked.forEach(function (item) {
            var w = Math.round((item.count / max) * 100);
            var pct = total > 0 ? Math.round((item.count / total) * 1000) / 10 : 0;
            h += '<div class="wa-bar-row">' +
                '<div class="wa-bar-label" style="width:160px;" title="' + escapeHtml(item.key) + '">' + escapeHtml(formatLabel(item.key)) + '</div>' +
                '<div class="wa-bar-track"><div class="wa-bar-fill" style="width:' + w + '%;background:' + color + ';"></div></div>' +
                '<div class="wa-bar-value" style="width:90px;text-align:right;font-size:10px;">' +
                    '<b style="color:' + color + ';">' + item.count + '</b> <span style="color:#888;">(' + pct + '%)</span>' +
                '</div></div>';
        });
        h += '</div>';
        return h;
    }

    function buildWeeklyRecordableTrend(cases, weeks) {
        var now = new Date();
        var buckets = [];
        for (var i = weeks - 1; i >= 0; i--) {
            var end = new Date(now); end.setDate(end.getDate() - (i * 7));
            var start = new Date(end); start.setDate(start.getDate() - 6);
            buckets.push({ start: start, end: end, total: 0, recordable: 0 });
        }
        cases.forEach(function (c) {
            var dt = c.incidentDateTime || c.reportedDateTime;
            if (!dt) return;
            var d = new Date(dt);
            if (isNaN(d)) return;
            for (var b = 0; b < buckets.length; b++) {
                if (d >= buckets[b].start && d <= buckets[b].end) {
                    buckets[b].total++;
                    if (c.recordable) buckets[b].recordable++;
                    break;
                }
            }
        });
        var labels = buckets.map(function (b) { return MONTH_SHORT[b.end.getMonth()] + ' ' + b.end.getDate(); });
        var recordables = buckets.map(function (b) { return b.recordable; });
        var rates = buckets.map(function (b) { return b.total > 0 ? Math.round((b.recordable / b.total) * 1000) / 10 : 0; });
        return { labels: labels, recordables: recordables, rates: rates };
    }

    function findRepeatRecordables(recs) {
        var byAlias = {};
        recs.forEach(function (c) {
            var a = c.alias || '(unknown)';
            if (!byAlias[a]) byAlias[a] = { alias: a, count: 0, cases: [] };
            byAlias[a].count++;
            byAlias[a].cases.push(c);
        });
        return Object.keys(byAlias)
            .map(function (k) { return byAlias[k]; })
            .filter(function (x) { return x.count >= 2; })
            .sort(function (a, b) { return b.count - a.count; });
    }

    function renderComplianceSection(a) {
        var body = ''; var totalAlerts = 0;
        function buildMissingAlert(icon, label, cases, fieldName) {
            if (cases.length === 0) return ''; totalAlerts += cases.length;
            var ddId = 'dd-compliance-' + fieldName; var isExpanded = expandedSections[ddId] || false;
            var h = '<div class="wa-compliance wa-compliance-orange" data-dd-id="' + ddId + '" data-dd-group="compliance" data-dd-value="' + fieldName + '"><span style="font-size:14px;">' + icon + '</span><span><strong>' + cases.length + '</strong> missing <strong>' + label + '</strong></span><div class="wa-bar-expand ' + (isExpanded ? 'open' : '') + '" style="margin-left:auto;">\u25B6</div></div>';
            if (isExpanded) h += buildDrilldownTable(cases, 'compliance', fieldName, [{ header: 'Body Part', getValue: function (c) { return c.principalBodyPart || '(missing)'; } }, { header: 'Location', getValue: function (c) { return c.incidentLocation || '(missing)'; } }]);
            return h;
        }
        body += '<div class="wa-sub-title">MISSING CASE DATA</div>';
        body += buildMissingAlert('\uD83E\uDDB4', 'Body Part', a.missingBodyPart, 'missingBodyPart');
        body += buildMissingAlert('\uD83D\uDCCD', 'Location', a.missingLocation, 'missingLocation');
        body += buildMissingAlert('\uD83D\uDEE4\uFE0F', 'Process Path', a.missingProcessPath, 'missingProcessPath');
        if (a.missingBodyPart.length === 0 && a.missingLocation.length === 0 && a.missingProcessPath.length === 0) body += '<div class="wa-compliance wa-compliance-green" style="cursor:default;">\u2705 All cases have body part, location, and process path</div>';

        body += '<div class="wa-divider"><div class="wa-sub-title">FOLLOW-UP & iCARE COMPLIANCE</div></div>';
        if (a.openMedicalCases.length === 0) { body += '<div class="wa-compliance wa-compliance-green" style="cursor:default;">\u2705 No open medical cases</div>'; }
        else {
            if (a.needsFollowUp.length > 0) { totalAlerts += a.needsFollowUp.length; var fuDdId = 'dd-followUp-needsFollowUp'; var fuExpanded = expandedSections[fuDdId] || false; body += '<div class="wa-compliance wa-compliance-red" data-dd-id="' + fuDdId + '" data-dd-group="followUp" data-dd-value="needsFollowUp"><span>\uD83D\uDCC5</span><span><strong>' + a.needsFollowUp.length + '</strong> need <strong>follow-up</strong></span><div class="wa-bar-expand ' + (fuExpanded ? 'open' : '') + '" style="margin-left:auto;">\u25B6</div></div>'; if (fuExpanded) { var fuCases = a.needsFollowUp.map(function (item) { return item.case; }); body += buildDrilldownTable(fuCases, 'followUp', 'needsFollowUp', [{ header: 'Last FU', getValue: function (c) { return c.latestFollowUpDate ? formatDateShort(c.latestFollowUpDate) : 'Never'; } }]); } }
            if (a.needsICare.length > 0) { totalAlerts += a.needsICare.length; var icDdId = 'dd-iCare-needsICare'; var icExpanded = expandedSections[icDdId] || false; body += '<div class="wa-compliance wa-compliance-red" data-dd-id="' + icDdId + '" data-dd-group="iCare" data-dd-value="needsICare"><span>\uD83D\uDC8A</span><span><strong>' + a.needsICare.length + '</strong> need <strong>iCare</strong></span><div class="wa-bar-expand ' + (icExpanded ? 'open' : '') + '" style="margin-left:auto;">\u25B6</div></div>'; if (icExpanded) { var icCases = a.needsICare.map(function (item) { return item.case; }); body += buildDrilldownTable(icCases, 'iCare', 'needsICare', [{ header: 'Last iCare', getValue: function (c) { return c.latestICareDate ? formatDateShort(c.latestICareDate) : 'Never'; } }]); } }
        }
        return buildSection('compliance', '\u26A0\uFE0F', 'Compliance', totalAlerts > 0 ? totalAlerts + ' issues' : 'All Clear', body, totalAlerts === 0);
    }

    function renderShiftSection(a, prevCounts) {
        var ranked = A.rankCounts(a.shiftCounts);
        if (ranked.length === 0) return '';
        var body = '<div class="wa-stats-grid">';
        ['FHD', 'FHN', 'BHD', 'BHN'].forEach(function (sk) { var info = a.shiftRecordable[sk] || { total: 0, recordable: 0 }; var color = PALETTE.shift[sk]; body += '<div class="wa-stat-card" style="border-top:3px solid ' + color + ';"><div class="wa-stat-value" style="color:' + color + ';">' + info.total + '</div><div class="wa-stat-label">' + sk + '</div><div style="margin-top:4px;font-size:9px;color:#888;">' + info.recordable + ' rec</div></div>'; });
        body += '</div>';
        body += buildBarChartWithDrilldown(ranked, a.totalCases, a.byShift, 'shift', { maxBars: 5, colorMap: PALETTE.shift, labelWidth: '130px', prevCounts: prevCounts ? prevCounts.shiftCounts : null, extraColumns: [{ header: 'Body Part', getValue: function (c) { return c.principalBodyPart || ''; } }, { header: 'Recordable', getValue: function (c) { return c.recordable ? 'YES' : 'No'; } }] });
        return buildSection('shift', '\uD83D\uDD04', 'Cases per Shift', '', body, false);
    }

    // ================================================================
    // PROCESS DEEP DIVE SECTION (MoM, per-shift, body part, repeat AAs)
    // ================================================================
    var _ddState = { process: 'Pick' };

    function renderProcessDeepDiveSection(a) {
        var settings = (WHSLib.state && WHSLib.state.settings) || {};
        if (settings.showAnalyticsProcessPath === false) return '';
        var year = currentFilters.year;
        var shiftFilter = currentFilters.shift || 'all';
        var dd = computeProcessDeepDive(_ddState.process, year, shiftFilter);
        var titleSuffix = shiftFilter !== 'all' ? ' · ' + shiftFilter + ' only' : '';

        var pickerOpts = PROCESS_PATHS_DEEP_DIVE.map(function (p) {
            return '<option value="' + escapeHtml(p) + '"' + (p === _ddState.process ? ' selected' : '') + '>' + escapeHtml(p) + '</option>';
        }).join('');

        var body = '';
        body += '<div style="display:flex;gap:10px;align-items:center;margin-bottom:14px;flex-wrap:wrap;">' +
            '<label style="font-size:11px;color:#888;">Process:</label>' +
            '<select id="wa-dd-picker" style="background:#0d1117;border:1px solid #2d333b;color:#e0e0e0;padding:5px 10px;border-radius:4px;font-size:12px;">' + pickerOpts + '</select>' +
            '<button id="wa-dd-export" class="wa-btn" style="margin-left:auto;background:#1976d2;color:#fff;border:none;border-radius:4px;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer;">📥 Export Deep Dive</button>' +
        '</div>';

        if (dd.totalCases === 0) {
            body += '<div class="wa-empty" style="padding:20px;text-align:center;color:#888;font-size:12px;">No cases for ' + escapeHtml(dd.processPath) + ' in ' + year + (shiftFilter !== 'all' ? ' on ' + shiftFilter : '') + '.</div>';
            return buildSection('deepdive', '🔬', 'Process Deep Dive — ' + dd.processPath + titleSuffix, year + ' · 0 cases', body, false);
        }

        // KPI row
        body += '<div class="wa-stats-grid-3" style="margin-bottom:14px;">' +
            '<div class="wa-stat-card" style="border-top:3px solid #ff9900;"><div class="wa-stat-value" style="color:#ff9900;">' + dd.totalCases + '</div><div class="wa-stat-label">Total cases</div></div>' +
            '<div class="wa-stat-card" style="border-top:3px solid #f44336;"><div class="wa-stat-value" style="color:#f44336;">' + dd.recordableCases + '</div><div class="wa-stat-label">Recordable</div></div>' +
            '<div class="wa-stat-card" style="border-top:3px solid #888;"><div class="wa-stat-value" style="color:#888;">' + dd.nwrCases + '</div><div class="wa-stat-label">NWR</div></div>' +
        '</div>';

        // Monthly rollup table with MoM%
        body += '<div class="wa-chart-container"><div class="wa-chart-title">📈 Monthly trend with MoM% — ' + dd.processPath + ' ' + year + '</div>';
        body += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:11px;">';
        body += '<thead><tr style="border-bottom:2px solid #21262d;">' +
            '<th style="text-align:left;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Month</th>' +
            '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Total</th>' +
            '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">MoM %</th>' +
            '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Rec</th>' +
            '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">NWR</th>' +
        '</tr></thead><tbody>';
        for (var mi = 0; mi < 12; mi++) {
            var row = dd.monthly[mi];
            var momColor = row.momPct > 10 ? '#f44336' : row.momPct < -10 ? '#4caf50' : '#888';
            var momText = mi === 0 ? '—' : (row.momPct >= 0 ? '+' : '') + row.momPct.toFixed(0) + '%';
            body += '<tr style="border-bottom:1px solid #1c2128;">' +
                '<td style="padding:6px;color:#e0e0e0;">' + MONTH_SHORT[mi] + '</td>' +
                '<td style="text-align:center;padding:6px;color:#e0e0e0;font-weight:bold;">' + row.total + '</td>' +
                '<td style="text-align:center;padding:6px;color:' + momColor + ';font-weight:bold;">' + momText + '</td>' +
                '<td style="text-align:center;padding:6px;color:#ef9a9a;">' + row.recordable + '</td>' +
                '<td style="text-align:center;padding:6px;color:#888;">' + row.nwr + '</td>' +
            '</tr>';
        }
        body += '</tbody></table></div></div>';

        // Per-shift table — only show rows that match the active shift filter
        var shiftsToShow = shiftFilter !== 'all' ? [shiftFilter] : ['FHD', 'FHN', 'BHD', 'BHN'];
        body += '<div class="wa-chart-container" style="margin-top:14px;"><div class="wa-chart-title">🔄 ' + (shiftFilter !== 'all' ? shiftFilter + ' monthly breakdown' : 'Per-shift monthly breakdown') + '</div>';
        body += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:11px;">';
        body += '<thead><tr style="border-bottom:2px solid #21262d;">' +
            '<th style="text-align:left;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Shift</th>';
        for (var hm = 0; hm < 12; hm++) body += '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">' + MONTH_SHORT[hm] + '</th>';
        body += '<th style="text-align:center;padding:6px;color:#ff9900;font-size:9px;text-transform:uppercase;">YTD</th>';
        body += '</tr></thead><tbody>';
        shiftsToShow.forEach(function (sk) {
            var months = dd.byShift[sk] || [];
            var ytd = 0;
            for (var ii = 0; ii < months.length; ii++) ytd += months[ii];
            body += '<tr style="border-bottom:1px solid #1c2128;"><td style="padding:6px;color:' + (PALETTE.shift[sk] || '#e0e0e0') + ';font-weight:bold;">' + sk + '</td>';
            for (var jm = 0; jm < 12; jm++) body += '<td style="text-align:center;padding:6px;color:' + (months[jm] ? '#e0e0e0' : '#444') + ';">' + (months[jm] || '·') + '</td>';
            body += '<td style="text-align:center;padding:6px;color:#ff9900;font-weight:bold;">' + ytd + '</td></tr>';
        });
        body += '</tbody></table></div></div>';

        // Top body parts (limit 8) — monthly trend matrix
        var bpEntries = Object.keys(dd.byBodyPart).map(function (k) {
            var sum = 0; for (var i = 0; i < 12; i++) sum += dd.byBodyPart[k][i];
            return { name: k, months: dd.byBodyPart[k], total: sum };
        }).sort(function (a, b) { return b.total - a.total; }).slice(0, 8);

        if (bpEntries.length) {
            body += '<div class="wa-chart-container" style="margin-top:14px;"><div class="wa-chart-title">🦴 Top body parts (monthly counts)</div>';
            body += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:11px;">';
            body += '<thead><tr style="border-bottom:2px solid #21262d;"><th style="text-align:left;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Body Part</th>';
            for (var bm = 0; bm < 12; bm++) body += '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">' + MONTH_SHORT[bm] + '</th>';
            body += '<th style="text-align:center;padding:6px;color:#ff9900;font-size:9px;text-transform:uppercase;">YTD</th></tr></thead><tbody>';
            bpEntries.forEach(function (bp) {
                body += '<tr style="border-bottom:1px solid #1c2128;"><td style="padding:6px;color:#e0e0e0;font-weight:bold;">' + escapeHtml(bp.name) + '</td>';
                for (var bbm = 0; bbm < 12; bbm++) body += '<td style="text-align:center;padding:6px;color:' + (bp.months[bbm] ? '#e0e0e0' : '#444') + ';">' + (bp.months[bbm] || '·') + '</td>';
                body += '<td style="text-align:center;padding:6px;color:#ff9900;font-weight:bold;">' + bp.total + '</td></tr>';
            });
            body += '</tbody></table></div></div>';
        }

        // Top injury types (limit 6)
        var injEntries = Object.keys(dd.byInjuryType).map(function (k) {
            var sum = 0; for (var i = 0; i < 12; i++) sum += dd.byInjuryType[k][i];
            return { name: k, months: dd.byInjuryType[k], total: sum };
        }).sort(function (a, b) { return b.total - a.total; }).slice(0, 6);

        if (injEntries.length) {
            body += '<div class="wa-chart-container" style="margin-top:14px;"><div class="wa-chart-title">🩹 Top injury types</div>';
            body += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:11px;">';
            body += '<thead><tr style="border-bottom:2px solid #21262d;"><th style="text-align:left;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Injury Type</th>';
            for (var im = 0; im < 12; im++) body += '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">' + MONTH_SHORT[im] + '</th>';
            body += '<th style="text-align:center;padding:6px;color:#ff9900;font-size:9px;text-transform:uppercase;">YTD</th></tr></thead><tbody>';
            injEntries.forEach(function (it) {
                body += '<tr style="border-bottom:1px solid #1c2128;"><td style="padding:6px;color:#e0e0e0;font-weight:bold;">' + escapeHtml(it.name) + '</td>';
                for (var iim = 0; iim < 12; iim++) body += '<td style="text-align:center;padding:6px;color:' + (it.months[iim] ? '#e0e0e0' : '#444') + ';">' + (it.months[iim] || '·') + '</td>';
                body += '<td style="text-align:center;padding:6px;color:#ff9900;font-weight:bold;">' + it.total + '</td></tr>';
            });
            body += '</tbody></table></div></div>';
        }

        // Repeat offenders
        if (dd.topAAs.length) {
            body += '<div class="wa-chart-container" style="margin-top:14px;"><div class="wa-chart-title">⚠️ Repeat offenders (2+ cases this year)</div>';
            body += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:11px;">';
            body += '<thead><tr style="border-bottom:2px solid #21262d;">' +
                '<th style="text-align:left;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Name</th>' +
                '<th style="text-align:left;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Alias</th>' +
                '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Cases</th>' +
                '<th style="text-align:center;padding:6px;color:#888;font-size:9px;text-transform:uppercase;">Recordable</th>' +
            '</tr></thead><tbody>';
            dd.topAAs.slice(0, 15).forEach(function (aa) {
                body += '<tr style="border-bottom:1px solid #1c2128;">' +
                    '<td style="padding:6px;color:#e0e0e0;">' + escapeHtml(aa.name) + '</td>' +
                    '<td style="padding:6px;color:#64b5f6;font-family:monospace;">' + escapeHtml(aa.alias || '') + '</td>' +
                    '<td style="text-align:center;padding:6px;color:#ff9900;font-weight:bold;">' + aa.count + '</td>' +
                    '<td style="text-align:center;padding:6px;color:#ef9a9a;">' + aa.recordable + '</td>' +
                '</tr>';
            });
            body += '</tbody></table></div></div>';
        }

        return buildSection('deepdive', '🔬', 'Process Deep Dive — ' + dd.processPath + titleSuffix, year + ' · ' + dd.totalCases + ' cases', body, true);
    }

    function renderBodyPartSection(a, prevCounts) {
        var ranked = A.rankCounts(a.bodyPartCounts, 20);
        if (ranked.length === 0) return '';
        var body = buildBarChartWithDrilldown(ranked, a.totalCases, a.byBodyPart, 'bodyPart', { maxBars: 15, colors: PALETTE.bodyPart, labelWidth: '110px', prevCounts: prevCounts ? prevCounts.bodyPartCounts : null, extraColumns: [{ header: 'Side', getValue: function (c) { return c.sideOfBody || ''; } }, { header: 'Diagnosis', getValue: function (c) { return c.diagnosisName || ''; } }] });
        return buildSection('bodypart', '\uD83E\uDDB4', 'Body Part Injuries', ranked.length + ' areas', body, false);
    }

    function renderLocationSection(a, prevCounts) {
        var ranked = A.rankCounts(a.locationCounts, 20);
        if (ranked.length === 0) return '';
        var body = buildBarChartWithDrilldown(ranked, a.totalCases, a.byLocation, 'location', { maxBars: 15, colors: PALETTE.location, labelWidth: '130px', prevCounts: prevCounts ? prevCounts.locationCounts : null, extraColumns: [{ header: 'Body Part', getValue: function (c) { return c.principalBodyPart || ''; } }, { header: 'Process Path', getValue: function (c) { return c.incidentProcessPath || ''; } }] });
        return buildSection('location', '\uD83D\uDCCD', 'Location Hotspots', ranked.length + ' locations', body, false);
    }

    // ================================================================
    // HEATMAP SECTION
    // ================================================================
    function renderHeatmapSection(a) {
        var settings = (WHSLib.state && WHSLib.state.settings) || {};
        if (settings.showAnalyticsHeatmaps === false) return '';
        var body = '';

        // ── Day of week ──────────────────────────────────────────────
        body += '<div class="wa-heatmap-container">';
        body += '<div class="wa-heatmap-title">Injuries by Day of Week</div>';
        body += '<div class="wa-heatmap-body">';
        body += A.buildHeatmapSVG(a.byDayOfWeek, A.DAY_LABELS, '', '#ff9900');
        body += '</div></div>';

        // ── Hour of day ──────────────────────────────────────────────
        body += '<div class="wa-heatmap-container">';
        body += '<div class="wa-heatmap-title">Injuries by Hour of Day (with shift bands)</div>';
        body += '<div class="wa-heatmap-body">';
        body += A.buildHourHeatmapSVG(a.byHourOfDay);
        body += '</div></div>';

        // ── Body part × shift matrix ─────────────────────────────────
        var topBPs = A.rankCounts(a.bodyPartCounts, 8).map(function(r){return r.key;});
        if (topBPs.length > 0) {
            body += '<div class="wa-heatmap-container">';
            body += '<div class="wa-heatmap-title">Body Part Frequency by Shift</div>';
            body += '<div class="wa-heatmap-body">';
            body += A.buildBodyPartShiftHeatmap(a.byShift, topBPs);
            body += '</div></div>';
        }

        // ── Peak insights ────────────────────────────────────────────
        var maxDay  = Math.max.apply(null, a.byDayOfWeek);
        var peakDay = a.byDayOfWeek.indexOf(maxDay);
        var maxHour  = Math.max.apply(null, a.byHourOfDay);
        var peakHour = a.byHourOfDay.indexOf(maxHour);

        // Find peak 3-hour window
        var windowMax = 0, windowStart = 0;
        for (var w = 0; w < 22; w++) {
            var ws = (a.byHourOfDay[w]||0) + (a.byHourOfDay[w+1]||0) + (a.byHourOfDay[w+2]||0);
            if (ws > windowMax) { windowMax = ws; windowStart = w; }
        }

        // Shift with most injuries
        var shiftKeys = Object.keys(a.shiftCounts);
        var peakShift = shiftKeys.length ? shiftKeys.sort(function(a,b){return (a.shiftCounts||0)-(b.shiftCounts||0);})[0] : null;
        var peakShiftCount = 0;
        shiftKeys.forEach(function(sk){ if ((a.shiftCounts[sk]||0) > peakShiftCount){ peakShift = sk; peakShiftCount = a.shiftCounts[sk]; }});

        body += '<div style="background:#161b22;border:1px solid #21262d;border-radius:6px;padding:8px 12px;margin-top:6px;">';
        body += '<div style="font-size:9px;color:#888;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">Key Insights</div>';
        body += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;font-size:10px;">';
        body += insight('Peak day', A.DAY_LABELS[peakDay] + ' (' + maxDay + ' cases)');
        body += insight('Peak hour', peakHour + ':00 (' + maxHour + ' cases)');
        body += insight('Peak 3hr window', windowStart + ':00–' + (windowStart+3) + ':00 (' + windowMax + ' cases)');
        if (peakShift) body += insight('Highest shift', peakShift + ' (' + peakShiftCount + ' cases)');
        body += '</div></div>';

        return buildSection('heatmap', '\uD83D\uDD25', 'Injury Heatmaps', 'Day, Hour & Shift', body, true);
    }

    function insight(label, value) {
        return '<div style="background:#0d1117;border:1px solid #21262d;border-radius:4px;padding:5px 8px;">' +
            '<div style="font-size:8px;color:#555;text-transform:uppercase;">' + escapeHtml(label) + '</div>' +
            '<div style="color:#ff9900;font-weight:600;">' + escapeHtml(value) + '</div></div>';
    }

    // PROCESS PATH SECTION
    // ================================================================
    function renderProcessPathSection(a, prevCounts) {
        var settings = (WHSLib.state && WHSLib.state.settings) || {};
        if (settings.showAnalyticsProcessPath === false) return '';
        var ranked = A.rankCounts(a.processPathCounts, 20);
        if (ranked.length === 0) return '';
        var body = buildBarChartWithDrilldown(ranked, a.totalCases, a.byProcessPath, 'processPath', {
            maxBars: 12, colors: PALETTE.location,
            labelWidth: '130px',
            prevCounts: prevCounts ? prevCounts.processPathCounts : null,
            extraColumns: [
                { header: 'Body Part', getValue: function (c) { return c.principalBodyPart || ''; } },
                { header: 'Shift', getValue: function (c) { return c._calcShiftCode || ''; } }
            ]
        });

        // Trend chart
        var year = currentFilters.year || new Date().getFullYear();
        var trendData = A.computeProcessPathTrend(year, 5);
        if (trendData && trendData.datasets.length > 0) {
            body += '<div style="margin-top:10px;">';
            body += '<div class="wa-sub-title">Monthly Trend \u2014 Top Paths</div>';
            body += '<div class="wa-chart-container"><div class="wa-chart-body" style="padding:8px;">';
            body += A.buildSVGLineChart(trendData.datasets, MONTH_SHORT, { width: 460, height: 180 });
            body += '</div></div></div>';
        }

        return buildSection('processpath', '\uD83D\uDEE3\uFE0F', 'Process Path Analysis', ranked.length + ' paths', body, true);
    }

    // ================================================================
    // PREDICTIVE PATTERNS SECTION
    // ================================================================
    function renderPredictiveSection(a) {
        var settings = (WHSLib.state && WHSLib.state.settings) || {};
        if (settings.showAnalyticsPredictive === false) return '';
        var patterns = A.computePredictivePatterns(a.cases);
        var watchList = A.computeWatchList(a.cases);

        var body = '';

        // ── Pattern flags ────────────────────────────────────────────
        if (patterns.length === 0 && watchList.length === 0) return '';

        if (patterns.length > 0) {
            body += '<div style="font-size:9px;color:#888;margin-bottom:8px;">Elevated injury frequency, recordable rate, and repeat-associate flags for the selected period.</div>';
            patterns.forEach(function(p) {
                var riskColors = { high:'#f44336', medium:'#ff9800', low:'#4caf50' };
                var riskBg     = { high:'rgba(244,67,54,.08)', medium:'rgba(255,152,0,.08)', low:'rgba(76,175,80,.06)' };
                var col = riskColors[p.risk] || '#888';
                var bg  = riskBg[p.risk]    || 'transparent';
                var icon = p.type === 'shift_path'         ? '\uD83D\uDEA8'
                         : p.type === 'body_path'          ? '\uD83E\uDDB4'
                         : p.type === 'repeat_associate'   ? '\uD83D\uDC64'
                         : p.type === 'days_since_recordable' ? '\uD83D\uDCC5'
                         : '\u26A0\uFE0F';
                body += '<div style="background:' + bg + ';border:1px solid ' + col + '33;border-radius:6px;padding:8px 10px;margin-bottom:6px;">';
                body += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px;">';
                body += '<span style="font-size:12px;">' + icon + '</span>';
                body += '<span style="font-size:10px;font-weight:bold;color:#e0e0e0;flex:1;">' + escapeHtml(p.title) + '</span>';
                body += '<span style="font-size:8px;font-weight:700;color:' + col + ';background:' + col + '22;padding:1px 6px;border-radius:3px;border:1px solid ' + col + '44;">' + p.risk.toUpperCase() + '</span>';
                body += '</div>';
                body += '<div style="font-size:9px;color:#888;">' + escapeHtml(p.detail) + '</div>';
                if (p.insight) {
                    body += '<div style="font-size:9px;color:#64b5f6;margin-top:3px;">\u2192 ' + escapeHtml(p.insight) + '</div>';
                }
                body += '</div>';
            });
        }

        // ── OMR Watch List ───────────────────────────────────────────
        if (watchList.length > 0) {
            body += '<div style="margin-top:10px;">';
            body += '<div style="font-size:9px;color:#888;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">\uD83D\uDC41 OMR Watch List (' + watchList.length + ' associates)</div>';
            body += '<div style="background:#161b22;border:1px solid #21262d;border-radius:6px;overflow:hidden;">';
            body += '<table style="width:100%;border-collapse:collapse;font-size:10px;">';
            body += '<thead><tr style="background:#1c2333;">';
            body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Alias</th>';
            body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Cases</th>';
            body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Rec.</th>';
            body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Top Body Part</th>';
            body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Last Injury</th>';
            body += '</tr></thead><tbody>';

            watchList.slice(0, 10).forEach(function(w, idx) {
                var topBP = Object.keys(w.bodyParts).sort(function(a,b){return w.bodyParts[b]-w.bodyParts[a];})[0] || '\u2014';
                var lastDate = w.lastDate ? w.lastDate.toLocaleDateString('en-US',{month:'short',day:'numeric'}) : '\u2014';
                var rowBg = idx % 2 === 0 ? '#161b22' : '#0d1117';
                var recColor = w.recordable > 0 ? '#f44336' : '#4caf50';
                body += '<tr style="background:' + rowBg + ';border-bottom:1px solid #21262d22;">';
                body += '<td style="padding:5px 8px;font-weight:600;color:#64b5f6;">' + escapeHtml(w.alias) + '</td>';
                body += '<td style="padding:5px 8px;text-align:center;font-weight:bold;color:' + (w.total>=3?'#f44336':'#ff9800') + ';">' + w.total + '</td>';
                body += '<td style="padding:5px 8px;text-align:center;color:' + recColor + ';font-weight:bold;">' + w.recordable + '</td>';
                body += '<td style="padding:5px 8px;color:#aaa;">' + escapeHtml(topBP) + '</td>';
                body += '<td style="padding:5px 8px;color:#666;">' + escapeHtml(lastDate) + '</td>';
                body += '</tr>';
            });

            body += '</tbody></table></div>';
            if (watchList.length > 10) {
                body += '<div style="font-size:9px;color:#555;text-align:center;padding:4px;">+' + (watchList.length-10) + ' more associates</div>';
            }
            body += '</div>';
        }

        var flagCount = patterns.length + (watchList.length > 0 ? 1 : 0);
        return buildSection('predictive', '\uD83D\uDCC8', 'Injury Patterns & Watch List', flagCount + ' items', body, true);
    }

    // ================================================================
    // RISK FORECAST SECTION
    // ================================================================
    var RISK_DAY_SHORT = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

    function _bandColor(b) {
        return b === 'HIGH' ? '#f44336' : b === 'ELEVATED' ? '#ff9800' : '#4caf50';
    }
    function _fmtProb(p) { return Math.round(p * 100) + '%'; }

    function _reasonPhrase(r) {
        var label = (A.FEATURE_LABELS && A.FEATURE_LABELS[r.feature]) || r.feature;
        var val = r.value;
        if (r.feature === 'soughtOutsideMedical' && val === 'yes') return 'Outside medical sought';
        if (r.feature === 'rwa' && val === 'yes') return 'RWA already active';
        if (r.feature === 'dafw' && val === 'yes') return 'DAFW already active';
        if (r.feature === 'associateRepeat' && val !== '0') return 'Associate has ' + val + ' prior injuries';
        if (r.feature === 'associateRepeatRec' && val !== '0') return 'Associate has ' + val + ' prior recordable' + (val === '1' ? '' : 's');
        if (r.feature === 'daysOpen') return 'Open ' + val + ' days';
        if (r.feature === 'hourBucket') return 'Time window ' + val;
        return label + ': ' + val;
    }

    function _peakDayLabel(p) {
        if (p.peakDay == null || p.peakDay < 0) return '';
        return 'Historically peaks ' + RISK_DAY_SHORT[p.peakDay] + '.';
    }

    function _watchTitle(p) {
        if (p.type === 'pp_bp')         return escapeHtml(p.processPath) + ' · ' + escapeHtml(p.bodyPart);
        if (p.type === 'pp_shift_hour') return escapeHtml(p.processPath) + ' · ' + escapeHtml(p.shift) + ' · ' + escapeHtml(p.hourBucket);
        if (p.type === 'loc_bp')        return escapeHtml(p.location)    + ' · ' + escapeHtml(p.bodyPart);
        return escapeHtml(p.key);
    }

    function _watchTypeLabel(t) {
        return t === 'pp_bp' ? 'Process path × Body part'
             : t === 'pp_shift_hour' ? 'Process path × Shift × Hour'
             : t === 'loc_bp' ? 'Location × Body part' : '';
    }

    // Pull ALL loaded bulk cases (every year in cache), ignoring the
    // Analytics panel's year/month/shift filters. Risk Forecast should
    // always use maximal history.
    function _getAllBulkCasesForForecast() {
        var out = [];
        if (!state || !state.bulkCaseData) return out;
        state.bulkCaseData.forEach(function (c) {
            if (!c) return;
            if (A.isNWRCase && A.isNWRCase(c)) return;
            var dt = c.incidentDateTime || c.reportedDateTime;
            if (!dt) return;
            var d = new Date(dt);
            if (isNaN(d)) return;
            // Ensure shift code is populated (may not be if never rendered)
            if (A.getShiftForCase) A.getShiftForCase(c);
            out.push(c);
        });
        return out;
    }

    function renderRiskForecastSection(a) {
        var settings = (WHSLib.state && WHSLib.state.settings) || {};
        if (settings.showAnalyticsRiskForecast === false) return '';
        if (!a || !a.cases || a.cases.length < 10) return '';

        // Risk Forecast uses ALL loaded cases regardless of year filter.
        var allBulk = _getAllBulkCasesForForecast();
        var forecast;
        try {
            forecast = A.computeRiskForecast(allBulk.length >= 10 ? allBulk : a.cases);
        } catch (e) {
            console.warn('Risk forecast compute failed:', e);
            return '';
        }
        a._riskForecast = forecast;
        var meta = forecast.meta;
        var est = forecast.nextInjuryEstimate;

        var body = '';

        // Header showing data source scope
        var scopeLine = 'Using ' + meta.totalCases + ' loaded cases across all years';
        if (est && est.firstCase && est.lastCase) {
            var fmtDate = function (d) { return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }); };
            scopeLine += ' · ' + fmtDate(est.firstCase) + ' → ' + fmtDate(est.lastCase);
        }
        body += '<div style="font-size:9px;color:#888;margin-bottom:8px;line-height:1.4;">' +
                scopeLine + '. Marginal probability estimate — rough directional guess, not a hard forecast.' +
                '</div>';

        if (!settings.showPriorYearCases) {
            body += '<div style="background:rgba(255,152,0,.08);border:1px solid #ff980033;border-radius:6px;padding:6px 10px;margin-bottom:10px;font-size:9px;color:#ffb74d;">' +
                    '💡 Enable <b>Load all prior-year cases</b> in Settings to include historical years for stronger signal.' +
                    '</div>';
        }

        // ── Next Injury Forecast — FLAGSHIP marginal estimate ──────
        body += '<div class="wa-sub-title" style="margin-top:6px;">🔮 Next Injury Forecast</div>';

        if (!est) {
            body += '<div style="background:rgba(255,152,0,.08);border:1px solid #ff980033;border-radius:6px;padding:10px;font-size:10px;color:#ffb74d;">' +
                    'Need at least 20 cases to produce a forecast. Currently have ' + (allBulk.length || 0) + '. Load more data or enable prior-year cases.' +
                    '</div>';
        } else {
            var dayName = RISK_DAY_SHORT[est.marginals.dayOfWeek[0].key];
            var predDateStr = est.predictedDate.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
            var whenHeadline;
            if (est.overdue) {
                whenHeadline = '<span style="color:#f44336;font-weight:700;">⚠️ OVERDUE</span> · site-wide mean gap is ' + est.meanGapDays + ' days, last incident was ' + est.daysSinceLast + ' days ago';
            } else {
                whenHeadline = '<span style="color:#ff9800;font-weight:700;">~' + predDateStr + '</span> · in about ' + est.expectedInDays + ' days (mean gap: ' + est.meanGapDays + ' days · last: ' + est.daysSinceLast + ' days ago)';
            }

            // ── Headline prediction card ──
            var top = {
                pp:  est.marginals.processPath[0],
                bp:  est.marginals.bodyPart[0],
                loc: est.marginals.location[0],
                sh:  est.marginals.shift[0],
                hb:  est.marginals.hourBucket[0],
                dow: est.marginals.dayOfWeek[0]
            };
            body += '<div style="background:linear-gradient(135deg,rgba(156,39,176,.12),rgba(255,152,0,.06));border:1px solid #9c27b066;border-left:4px solid #9c27b0;border-radius:8px;padding:12px;margin-bottom:10px;">';
            body += '<div style="font-size:10px;font-weight:700;color:#ce93d8;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;">Most-likely next injury profile (marginal mode)</div>';
            body += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 16px;font-size:11px;">';
            function profileRow(icon, label, pick) {
                if (!pick) return '';
                var share = Math.round(pick.share * 100);
                var val = typeof pick.key === 'number' ? RISK_DAY_SHORT[pick.key] : pick.key;
                return '<div><span style="color:#888;">' + icon + ' ' + label + '</span>: <b style="color:#e0e0e0;">' + escapeHtml(String(val)) + '</b> <span style="color:#9c27b0;font-weight:700;">(' + share + '%)</span></div>';
            }
            body += profileRow('📍', 'Process path', top.pp);
            body += profileRow('🦴', 'Body part',    top.bp);
            body += profileRow('🏢', 'Location',     top.loc);
            body += profileRow('🕐', 'Shift',        top.sh);
            body += profileRow('📅', 'Day of week',  top.dow);
            body += profileRow('⏰', 'Hour window',  top.hb);
            body += '</div>';
            body += '<div style="font-size:11px;color:#e0e0e0;margin-top:10px;padding-top:10px;border-top:1px solid #9c27b033;">🗓️ Next expected: ' + whenHeadline + '</div>';
            body += '</div>';

            // ── Top 5 joint scenarios ──
            body += '<div style="font-size:10px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">Top 5 joint scenarios (independence-estimated)</div>';
            est.scenarios.forEach(function (sc, idx) {
                var dowLabel = RISK_DAY_SHORT[sc.dayOfWeek];
                var jointPct = (sc.jointProb * 100).toFixed(2);
                var basis = sc.actualCount > 0
                    ? '<span style="color:#4caf50;">' + sc.actualCount + ' matching historical case' + (sc.actualCount === 1 ? '' : 's') + '</span>'
                    : '<span style="color:#666;">no exact matches (profile inferred)</span>';
                var borderColor = idx === 0 ? '#ff9800' : '#555';
                body += '<div style="background:#161b22;border:1px solid #21262d;border-left:3px solid ' + borderColor + ';border-radius:6px;padding:8px 10px;margin-bottom:5px;">';
                body += '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;">';
                body += '<div style="font-size:11px;font-weight:600;color:#e0e0e0;">';
                body += '<span style="color:#ce93d8;">#' + (idx + 1) + '</span> ';
                body += escapeHtml(sc.processPath) + ' · ';
                body += '<span style="color:#ffb74d;">' + escapeHtml(sc.bodyPart) + '</span> · ';
                body += sc.shift + ' · ' + dowLabel + ' · ' + sc.hourBucket;
                body += '</div>';
                body += '<div style="font-size:9px;color:#888;white-space:nowrap;">' + jointPct + '% joint · ' + basis + '</div>';
                body += '</div>';
                body += '</div>';
            });

            // ── Full marginal breakdowns (the distribution evidence) ──
            body += '<details style="margin-top:8px;"><summary style="cursor:pointer;font-size:10px;color:#888;user-select:none;">📊 Full distribution breakdown ▸</summary>';
            body += '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:8px;">';
            function distColumn(title, list, labelFn) {
                var h = '<div style="background:#161b22;border:1px solid #21262d;border-radius:6px;padding:8px;">';
                h += '<div style="font-size:9px;color:#888;font-weight:700;text-transform:uppercase;margin-bottom:6px;">' + title + '</div>';
                list.slice(0, 5).forEach(function (item) {
                    var lbl = labelFn ? labelFn(item.key) : item.key;
                    h += '<div style="display:flex;justify-content:space-between;font-size:10px;padding:3px 0;">';
                    h += '<span style="color:#ccc;">' + escapeHtml(String(lbl)) + '</span>';
                    h += '<span style="color:#9c27b0;font-weight:700;">' + Math.round(item.share * 100) + '%</span>';
                    h += '</div>';
                });
                h += '</div>';
                return h;
            }
            body += distColumn('Process path', est.marginals.processPath);
            body += distColumn('Body part',    est.marginals.bodyPart);
            body += distColumn('Location',     est.marginals.location);
            body += distColumn('Shift',        est.marginals.shift);
            body += distColumn('Day of week',  est.marginals.dayOfWeek, function (k) { return RISK_DAY_SHORT[k]; });
            body += distColumn('Hour window',  est.marginals.hourBucket);
            body += '</div>';
            body += '</details>';
        }

        // Safety Focus (3 columns)
        body += '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:12px;">';

        body += '<div style="background:#161b22;border:1px solid #21262d;border-radius:6px;padding:10px;">';
        body += '<div style="font-size:9px;color:#888;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">📍 Focus Locations (90d)</div>';
        if (forecast.focusLocations.length === 0) {
            body += '<div style="font-size:10px;color:#555;">No recordables in last 90 days.</div>';
        } else {
            forecast.focusLocations.forEach(function (l) {
                body += '<div style="padding:6px 0;border-top:1px solid #21262d;">';
                body += '<div style="font-size:11px;font-weight:600;color:#e0e0e0;">' + escapeHtml(l.location) + '</div>';
                body += '<div style="font-size:9px;color:#f44336;">' + l.count + ' recordable' + (l.count === 1 ? '' : 's') +
                        (l.topBodyPart ? ' · top: ' + escapeHtml(l.topBodyPart) : '') + '</div>';
                body += '</div>';
            });
        }
        body += '</div>';

        body += '<div style="background:#161b22;border:1px solid #21262d;border-radius:6px;padding:10px;">';
        body += '<div style="font-size:9px;color:#888;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">🦴 Watch Body Parts</div>';
        if (forecast.watchBodyParts.length === 0) {
            body += '<div style="font-size:10px;color:#555;">No body part data in recent period.</div>';
        } else {
            forecast.watchBodyParts.forEach(function (bp) {
                var arrow = bp.accelerating ? '⬆️ ' : '';
                var color = bp.accelerating ? '#ff9800' : '#888';
                body += '<div style="padding:6px 0;border-top:1px solid #21262d;">';
                body += '<div style="font-size:11px;font-weight:600;color:#e0e0e0;">' + arrow + escapeHtml(bp.bodyPart) + '</div>';
                body += '<div style="font-size:9px;color:' + color + ';">' + bp.recent + ' in last 28d · prior 12w avg: ' + (bp.base / 12).toFixed(1) + '/wk</div>';
                body += '</div>';
            });
        }
        body += '</div>';

        body += '<div style="background:#161b22;border:1px solid #21262d;border-radius:6px;padding:10px;">';
        body += '<div style="font-size:9px;color:#888;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">🎯 Chase These Open Cases</div>';
        if (forecast.openScored.length === 0) {
            body += '<div style="font-size:10px;color:#555;">No open cases to score.</div>';
        } else {
            forecast.openScored.slice(0, 5).forEach(function (s) {
                var bc = _bandColor(s.band);
                var reason = s.topReasons[0] ? _reasonPhrase(s.topReasons[0]) : 'Baseline';
                body += '<div style="padding:6px 0;border-top:1px solid #21262d;">';
                body += '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;">';
                body += '<span style="font-size:10px;font-weight:600;color:#64b5f6;">' + escapeHtml(s.caseNumber || '') + '</span>';
                body += '<span style="font-size:11px;font-weight:700;color:' + bc + ';">' + _fmtProb(s.probability) + '</span>';
                body += '</div>';
                body += '<div style="font-size:9px;color:#aaa;">' + escapeHtml(s.alias || '—') + ' · ' + escapeHtml(reason) + '</div>';
                body += '</div>';
            });
        }
        body += '</div>';
        body += '</div>';

        // Watch Predictions
        if (settings.showAnalyticsRiskWatch !== false) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">⚠️ Watch Predictions</div>';
            body += '<div style="font-size:9px;color:#888;margin-bottom:6px;">Recurring patterns from closed cases that are still producing incidents. Cited by count.</div>';
            if (forecast.watchPatterns.length === 0) {
                body += '<div style="font-size:10px;color:#555;padding:8px;">No recurring recordable patterns in current data.</div>';
            } else {
                forecast.watchPatterns.slice(0, 5).forEach(function (p, idx) {
                    var rate = Math.round(p.rate * 100);
                    var last = p.lastDaysAgo <= 1 ? 'yesterday' : 'last occurred ' + p.lastDaysAgo + ' days ago';
                    body += '<div style="background:rgba(244,67,54,.06);border:1px solid #f4433633;border-left:3px solid #f44336;border-radius:6px;padding:8px 10px;margin-bottom:6px;">';
                    body += '<div style="display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px;">';
                    body += '<div style="font-size:11px;font-weight:700;color:#e0e0e0;">' + _watchTitle(p) + '</div>';
                    body += '<div style="font-size:8px;font-weight:700;color:#f44336;background:rgba(244,67,54,.2);padding:1px 6px;border-radius:3px;">#' + (idx + 1) + '</div>';
                    body += '</div>';
                    body += '<div style="font-size:10px;color:#e0e0e0;"><b>' + p.rec + ' of ' + p.total + '</b> became recordable (<b>' + rate + '%</b>).</div>';
                    body += '<div style="font-size:9px;color:#aaa;margin-top:3px;">' + _watchTypeLabel(p.type) + ' · ' + last + '. ' + _peakDayLabel(p) + '</div>';
                    body += '</div>';
                });
            }
        }

        // Open Case Risk Board
        if (settings.showAnalyticsRiskClassifier !== false) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">🎯 Open Case Risk Board</div>';
            if (!forecast.model || forecast.meta.closedCount < 30) {
                body += '<div style="background:rgba(255,152,0,.08);border:1px solid #ff980033;border-radius:6px;padding:8px 10px;font-size:10px;color:#ffb74d;">' +
                        'Need at least 30 closed cases to score open cases. Currently have ' + forecast.meta.closedCount + '. Enable prior-year loading in settings.' +
                        '</div>';
            } else if (forecast.openScored.length === 0) {
                body += '<div style="font-size:10px;color:#555;padding:8px;">No open cases.</div>';
            } else {
                body += '<div style="font-size:9px;color:#888;margin-bottom:6px;">Baseline rate: <b>' + _fmtProb(forecast.meta.baseRate) + '</b> · Trained on ' + forecast.meta.closedCount + ' closed cases.</div>';
                body += '<div style="background:#161b22;border:1px solid #21262d;border-radius:6px;overflow:hidden;">';
                body += '<table style="width:100%;border-collapse:collapse;font-size:10px;">';
                body += '<thead><tr style="background:#1c2333;">';
                body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Case</th>';
                body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Alias</th>';
                body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Prob.</th>';
                body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Band</th>';
                body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Top Reasons</th>';
                body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Open (d)</th>';
                body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Similar Closed</th>';
                body += '</tr></thead><tbody>';

                forecast.openScored.slice(0, 20).forEach(function (s, idx) {
                    var bc = _bandColor(s.band);
                    var reasonsTxt = s.topReasons.length > 0 ?
                        s.topReasons.map(function (r) { return escapeHtml(_reasonPhrase(r)); }).join(' · ') :
                        '<i style="color:#555;">near baseline</i>';
                    var sim = s.similar;
                    var simTxt = (sim && sim.totalCount > 0) ?
                        (sim.recordableCount + '/' + sim.totalCount + ' rec' + (sim.matchLevel === 'processPath' ? ' *' : '')) :
                        '<i style="color:#555;">none</i>';
                    var rowBg = idx % 2 === 0 ? '#161b22' : '#0d1117';
                    var href = A.buildIncidentUrl(s._case);
                    body += '<tr style="background:' + rowBg + ';border-bottom:1px solid #21262d22;">';
                    body += '<td style="padding:5px 8px;font-weight:600;"><a href="' + href + '" target="_blank" style="color:#64b5f6;">' + escapeHtml(s.caseNumber || '—') + '</a></td>';
                    body += '<td style="padding:5px 8px;color:#aaa;">' + escapeHtml(s.alias || '—') + '</td>';
                    body += '<td style="padding:5px 8px;text-align:center;font-weight:700;color:' + bc + ';">' + _fmtProb(s.probability) + '</td>';
                    body += '<td style="padding:5px 8px;text-align:center;"><span style="font-size:8px;font-weight:700;color:' + bc + ';background:' + bc + '22;padding:2px 6px;border-radius:3px;">' + s.band + '</span></td>';
                    body += '<td style="padding:5px 8px;color:#ccc;">' + reasonsTxt + '</td>';
                    body += '<td style="padding:5px 8px;text-align:center;color:#888;">' + (s.daysOpen != null ? s.daysOpen : '—') + '</td>';
                    body += '<td style="padding:5px 8px;color:#aaa;">' + simTxt + '</td>';
                    body += '</tr>';
                });

                body += '</tbody></table></div>';
                if (forecast.openScored.length > 20) {
                    body += '<div style="font-size:9px;color:#555;text-align:center;padding:4px;">+' + (forecast.openScored.length - 20) + ' more open cases</div>';
                }
            }
        }

        // At-Risk Associates (score + cohort)
        var watchList2 = A.computeWatchList(a.cases);
        if (watchList2.length > 0) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">👤 At-Risk Associates</div>';
            body += '<div style="background:#161b22;border:1px solid #21262d;border-radius:6px;overflow:hidden;">';
            body += '<table style="width:100%;border-collapse:collapse;font-size:10px;">';
            body += '<thead><tr style="background:#1c2333;">';
            body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Score</th>';
            body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Cohort</th>';
            body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Alias</th>';
            body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Total / Rec</th>';
            body += '<th style="padding:6px 8px;text-align:center;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Last</th>';
            body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Repeat Body Part</th>';
            body += '<th style="padding:6px 8px;text-align:left;color:#888;font-size:8px;font-weight:700;text-transform:uppercase;">Flagged</th>';
            body += '</tr></thead><tbody>';

            var scored2 = watchList2.map(function (w) {
                var recency = w.lastDate ? Math.floor((Date.now() - w.lastDate.getTime()) / 86400000) : 999;
                var bpKeys = Object.keys(w.bodyParts);
                bpKeys.sort(function (aa, bb) { return w.bodyParts[bb] - w.bodyParts[aa]; });
                var topBP = bpKeys[0];
                var bpRepeat = topBP ? w.bodyParts[topBP] : 0;
                var score = Math.round(
                    30 * Math.min(w.total, 5) / 5 +
                    25 * Math.min(w.recordable, 3) / 3 +
                    20 * Math.max(0, 1 - recency / 90) +
                    15 * Math.min(bpRepeat, 3) / 3 +
                    10 * (w.recordable > 0 && recency <= 30 ? 1 : 0)
                );
                var cohort = 'MONITOR';
                var reasons = [];
                if (w.total >= 3) { cohort = 'WATCH'; reasons.push(w.total + ' total injuries'); }
                if (w.total >= 2 && w.recordable >= 1 && recency <= 30) { cohort = 'WATCH'; reasons.push('recent recordable'); }
                if (bpRepeat >= 2 && recency <= 60) { cohort = 'WATCH'; reasons.push('repeat ' + topBP); }
                if (reasons.length === 0) reasons.push(w.total + ' injuries in period');
                return { w: w, score: score, cohort: cohort, recency: recency, topBP: topBP, bpRepeat: bpRepeat, reasons: reasons };
            }).sort(function (aa, bb) { return bb.score - aa.score; });

            scored2.slice(0, 15).forEach(function (row, idx) {
                var cohortColor = row.cohort === 'WATCH' ? '#f44336' : '#ff9800';
                var rowBg = idx % 2 === 0 ? '#161b22' : '#0d1117';
                var lastStr = row.w.lastDate ? row.recency + 'd ago' : '—';
                var bpCell = row.topBP ? escapeHtml(row.topBP) + (row.bpRepeat >= 2 ? ' (' + row.bpRepeat + ')' : '') : '—';
                body += '<tr style="background:' + rowBg + ';border-bottom:1px solid #21262d22;">';
                body += '<td style="padding:5px 8px;text-align:center;font-weight:700;color:' + cohortColor + ';font-size:12px;">' + row.score + '</td>';
                body += '<td style="padding:5px 8px;text-align:center;"><span style="font-size:8px;font-weight:700;color:' + cohortColor + ';background:' + cohortColor + '22;padding:2px 6px;border-radius:3px;">' + row.cohort + '</span></td>';
                body += '<td style="padding:5px 8px;font-weight:600;color:#64b5f6;">' + escapeHtml(row.w.alias) + '</td>';
                body += '<td style="padding:5px 8px;text-align:center;color:#ccc;">' + row.w.total + ' / <span style="color:#f44336;font-weight:700;">' + row.w.recordable + '</span></td>';
                body += '<td style="padding:5px 8px;text-align:center;color:#888;">' + lastStr + '</td>';
                body += '<td style="padding:5px 8px;color:#aaa;">' + bpCell + '</td>';
                body += '<td style="padding:5px 8px;color:#888;font-size:9px;">' + escapeHtml(row.reasons.join(', ')) + '</td>';
                body += '</tr>';
            });

            body += '</tbody></table></div>';
        }

        // Recordable Description Clusters (lazy trigger)
        if (settings.showAnalyticsRiskClusters !== false && a.recordableCases && a.recordableCases.length >= 4) {
            body += '<div class="wa-sub-title" style="margin-top:14px;">🔎 Recordable Patterns — Description Clusters</div>';
            body += '<div id="wa-risk-clusters" style="min-height:40px;">';
            body += '<button type="button" data-wa-risk-cluster-trigger="1" style="background:#1c2333;border:1px solid #30363d;color:#64b5f6;padding:6px 12px;border-radius:4px;cursor:pointer;font-size:10px;">' +
                    'Analyze ' + a.recordableCases.length + ' recordable descriptions →' +
                    '</button>';
            body += '<div style="font-size:9px;color:#666;margin-top:4px;">Click to run TF-IDF clustering of recordable incident narratives.</div>';
            body += '</div>';
        }

        var badgeParts = [];
        if (forecast.nextInjuryEstimate) {
            badgeParts.push(forecast.nextInjuryEstimate.overdue ? 'overdue' : '~' + forecast.nextInjuryEstimate.expectedInDays + 'd');
        }
        if (forecast.openScored.length > 0) {
            var flaggedCount = forecast.openScored.filter(function (x) { return x.band !== 'BASELINE'; }).length;
            if (flaggedCount > 0) badgeParts.push(flaggedCount + ' flagged open');
        }
        var badge = badgeParts.join(' · ') || 'active';

        return buildSection('riskforecast', '🔮', 'Risk Forecast', badge, body, false);
    }

    // ================================================================
    // INJURIES BY MANAGER (v1 roster + v2 per-manager deep dive)
    // Pivots existing bulk case data on `managerAlias` (already parsed at
    // [bulk parser:1650]). No new fetches — pure aggregation + render.
    // ================================================================

    // Module state for the manager section: sort column, sort direction,
    // filters, and which manager's deep-dive panel is currently open.
    var _mgrState = {
        sort: { col: 'count', dir: 'desc' },
        filters: { minCases: 1, trackedOnly: false, includeFlex: true },
        openManager: null
    };

    function computeManagerAggregates(cases, siteRecordableRate, trackedAliases) {
        var byMgr = {};
        var today = new Date();
        var thirtyAgo = new Date(today.getTime() - 30 * 86400000);

        for (var i = 0; i < cases.length; i++) {
            var c = cases[i];
            var m = (c.managerAlias || '').toLowerCase().trim();
            if (!m) continue;
            if (!byMgr[m]) {
                byMgr[m] = {
                    alias: m, count: 0, recordable: 0, nearMiss: 0, openCount: 0,
                    dafw: 0, rwa: 0, severeCount: 0, last30: 0,
                    bodyParts: {}, processPaths: {}, cases: []
                };
            }
            var rec = byMgr[m];
            rec.count++;
            rec.cases.push(c);
            if (c.recordable) rec.recordable++;
            if (c.type === 'NEAR_MISS') rec.nearMiss++;
            var med = (c.latestMedicalStatus || '').toLowerCase();
            if (med === 'open' || med === 'pending-outside-medical') rec.openCount++;
            if (c.dafwActive || (c.dafwDays && c.dafwDays > 0)) rec.dafw++;
            if (c.rwaActive || (c.rwaDays && c.rwaDays > 0)) rec.rwa++;
            var sev = (c.diagnosisSeverity || '').toLowerCase();
            if (sev === 'critical' || sev === 'high') rec.severeCount++;
            var dt = c.incidentDateTime || c.reportedDateTime;
            if (dt) { var d = new Date(dt); if (!isNaN(d) && d >= thirtyAgo) rec.last30++; }
            if (c.principalBodyPart) rec.bodyParts[c.principalBodyPart] = (rec.bodyParts[c.principalBodyPart] || 0) + 1;
            if (c.incidentProcessPath) rec.processPaths[c.incidentProcessPath] = (rec.processPaths[c.incidentProcessPath] || 0) + 1;
        }

        // Finalize: derived stats + top body part / process path lookups
        var arr = [];
        Object.keys(byMgr).forEach(function (k) {
            var r = byMgr[k];
            r.recordableRate = r.count > 0 ? Math.round((r.recordable / r.count) * 1000) / 10 : 0;
            r.vsAvg = siteRecordableRate > 0 ? Math.round((r.recordableRate - siteRecordableRate) * 10) / 10 : 0;
            r.topBodyPart = topKeyOf(r.bodyParts);
            r.topProcessPath = topKeyOf(r.processPaths);
            r.isTracked = trackedAliases ? !!trackedAliases[k] : false;
            arr.push(r);
        });
        return arr;
    }

    function topKeyOf(countsObj) {
        var top = null, max = 0;
        Object.keys(countsObj).forEach(function (k) { if (countsObj[k] > max) { max = countsObj[k]; top = k; } });
        return top;
    }

    function buildTrackedAliasMap() {
        // Pull the current site's tracked-personnel manager aliases for the
        // "Tracked Only" filter. Cheap — used once per render.
        var map = {};
        try {
            var site = (state.settings && state.settings.siteCode) || '';
            if (site && lib.trackedPersonnel && lib.trackedPersonnel.get) {
                var list = lib.trackedPersonnel.get(site) || [];
                list.forEach(function (p) { if (p.alias) map[String(p.alias).toLowerCase()] = true; });
            }
        } catch (e) {}
        return map;
    }

    function applyMgrFilters(rows, filters) {
        return rows.filter(function (r) {
            if (r.count < (filters.minCases || 1)) return false;
            if (filters.trackedOnly && !r.isTracked) return false;
            // FLEX filter: if includeFlex is false, drop managers whose cases
            // are predominantly FLEX (employeeType FLEX). Cheap heuristic.
            if (!filters.includeFlex) {
                var flex = 0;
                for (var i = 0; i < r.cases.length; i++) {
                    if ((r.cases[i].employeeType || '').toUpperCase().indexOf('FLEX') !== -1) flex++;
                }
                if (flex / r.cases.length >= 0.6) return false;
            }
            return true;
        });
    }

    function sortMgrRows(rows, sort) {
        var col = sort.col, dir = sort.dir === 'asc' ? 1 : -1;
        return rows.slice().sort(function (a, b) {
            var av = a[col], bv = b[col];
            // Alphabetical for string columns
            if (typeof av === 'string' || typeof bv === 'string') {
                av = String(av || '').toLowerCase();
                bv = String(bv || '').toLowerCase();
                return av < bv ? -1 * dir : av > bv ? 1 * dir : 0;
            }
            return ((av || 0) - (bv || 0)) * dir;
        });
    }

    function renderManagerSection(a, prevCounts) {
        var settings = (WHSLib.state && WHSLib.state.settings) || {};
        if (settings.showAnalyticsManagerSection === false) return '';
        if (!a.cases || a.cases.length === 0) return '';

        var trackedMap = buildTrackedAliasMap();
        var allRows = computeManagerAggregates(a.cases, a.recordableRate || 0, trackedMap);
        if (allRows.length === 0) {
            return buildSection('mgr', '👤', 'Injuries by Manager', '0 managers',
                '<div class="wa-empty">No manager data on the loaded cases.</div>', true);
        }

        var rows = sortMgrRows(applyMgrFilters(allRows, _mgrState.filters), _mgrState.sort);

        // ── Hero KPIs ──────────────────────────────────────────────
        var allMgrCount = allRows.length;
        var top = allRows.slice().sort(function (a2, b) { return b.count - a2.count; })[0];
        // Highest conv. rate among managers with ≥3 cases (denoise tiny samples)
        var convCandidates = allRows.filter(function (r) { return r.count >= 3; });
        var highConv = convCandidates.slice().sort(function (a2, b) { return b.recordableRate - a2.recordableRate; })[0];
        var mostRecent = allRows.slice().sort(function (a2, b) { return b.last30 - a2.last30; })[0];

        var siteAvg = a.recordableRate || 0;
        // Attribution caveat — this section pivots on injuredPersonData.managerAlias
        // which is FCLM's auto-filled direct-report manager, not the AM who actually
        // wrote up the case. Austin has no reliable field for the reporting manager,
        // so users should read these numbers as "who's on the injured AA's team",
        // not "who dealt with the incident".
        var body = '<div style="background:#3e2723;border:1px solid #ff9800;border-radius:6px;padding:8px 12px;margin-bottom:14px;font-size:11px;color:#ffcc80;display:flex;gap:8px;align-items:center;">';
        body += '<span style="font-size:14px;">⚠️</span>';
        body += '<span><b>Attributed to FCLM direct-report manager, not always the reporting manager.</b> Austin\'s bulk data doesn\'t reliably identify the AM who wrote up each case — this section groups by the injured AA\'s FCLM manager instead.</span>';
        body += '</div>';

        body += '<div class="wa-stats-grid" style="margin-bottom:14px;">';
        body += '<div class="wa-stat-card" style="border-top:3px solid #2196f3;"><div class="wa-stat-value" style="color:#2196f3;">' + allMgrCount + '</div><div class="wa-stat-label">Managers w/ Cases</div><div style="font-size:9px;margin-top:4px;color:#888;">site avg ' + siteAvg + '% rec.</div></div>';
        body += '<div class="wa-stat-card" style="border-top:3px solid #f44336;"><div class="wa-stat-value" style="color:#f44336;">' + (top ? top.count : 0) + '</div><div class="wa-stat-label">Top Manager</div><div style="font-size:9px;margin-top:4px;color:#888;">' + (top ? escapeHtml(top.alias) : '—') + '</div></div>';
        body += '<div class="wa-stat-card" style="border-top:3px solid #ff9800;"><div class="wa-stat-value" style="color:#ff9800;">' + (highConv ? highConv.recordableRate + '%' : '—') + '</div><div class="wa-stat-label">Highest Conv. Rate</div><div style="font-size:9px;margin-top:4px;color:#888;">' + (highConv ? escapeHtml(highConv.alias) + ' (≥3 cases)' : 'no manager with ≥3 cases') + '</div></div>';
        body += '<div class="wa-stat-card" style="border-top:3px solid #9c27b0;"><div class="wa-stat-value" style="color:#9c27b0;">' + (mostRecent ? mostRecent.last30 : 0) + '</div><div class="wa-stat-label">Most Active (30d)</div><div style="font-size:9px;margin-top:4px;color:#888;">' + (mostRecent ? escapeHtml(mostRecent.alias) : '—') + '</div></div>';
        body += '</div>';

        // ── Filter bar ─────────────────────────────────────────────
        body += '<div style="display:flex;gap:14px;align-items:center;margin-bottom:10px;font-size:11px;color:#aaa;flex-wrap:wrap;padding:8px 10px;background:#161b22;border-radius:6px;border:1px solid #21262d;">';
        body += '<label style="display:flex;align-items:center;gap:6px;">Min cases: ' +
            '<select id="wa-mgr-mincases" style="background:#0d1117;color:#e0e0e0;border:1px solid #2d333b;border-radius:4px;padding:2px 6px;font-size:11px;">' +
            [1, 2, 3, 5, 10].map(function (n) { return '<option value="' + n + '"' + (_mgrState.filters.minCases === n ? ' selected' : '') + '>' + n + '+</option>'; }).join('') +
            '</select></label>';
        body += '<label style="display:flex;align-items:center;gap:6px;cursor:pointer;"><input type="checkbox" id="wa-mgr-tracked"' + (_mgrState.filters.trackedOnly ? ' checked' : '') + '> Tracked only</label>';
        body += '<label style="display:flex;align-items:center;gap:6px;cursor:pointer;"><input type="checkbox" id="wa-mgr-flex"' + (_mgrState.filters.includeFlex ? ' checked' : '') + '> Include FLEX-heavy teams</label>';
        body += '<span style="margin-left:auto;color:#666;">' + rows.length + ' of ' + allRows.length + ' managers shown</span>';
        body += '</div>';

        // ── Roster table ───────────────────────────────────────────
        body += '<div style="overflow-x:auto;max-height:560px;overflow-y:auto;border:1px solid #21262d;border-radius:6px;">';
        body += '<table class="wa-drilldown-table" style="width:100%;font-size:11px;">';
        body += '<thead><tr>' + buildMgrHeaderCells() + '</tr></thead><tbody>';

        if (rows.length === 0) {
            body += '<tr><td colspan="11" style="text-align:center;color:#888;padding:20px;">No managers match the current filters.</td></tr>';
        } else {
            rows.forEach(function (r) { body += renderMgrRow(r, siteAvg); });
        }

        body += '</tbody></table></div>';

        // Hint
        body += '<div style="font-size:10px;color:#666;margin-top:8px;">Click a manager\'s alias to open their deep-dive panel (12-week trend, body parts, process paths, severity, time-of-day, open cases).</div>';

        var badge = allMgrCount + ' mgrs · top: ' + (top ? top.alias + ' (' + top.count + ')' : '—');
        return buildSection('mgr', '👤', 'Injuries by Manager', badge, body, false);
    }

    function buildMgrHeaderCells() {
        var cols = [
            { id: 'alias',           label: 'Manager',         w: '120px', align: 'left' },
            { id: 'count',           label: 'Cases',           w: '60px',  align: 'right' },
            { id: 'recordable',      label: 'Rec.',            w: '50px',  align: 'right' },
            { id: 'recordableRate',  label: 'Conv. %',         w: '70px',  align: 'right' },
            { id: 'nearMiss',        label: 'NM',              w: '40px',  align: 'right' },
            { id: 'severeCount',     label: 'Severe',          w: '60px',  align: 'right' },
            { id: 'dafw',            label: 'DAFW',            w: '50px',  align: 'right' },
            { id: 'rwa',             label: 'RWA',             w: '50px',  align: 'right' },
            { id: 'openCount',       label: 'Open',            w: '50px',  align: 'right' },
            { id: 'topBodyPart',     label: 'Top Body Part',   w: '120px', align: 'left' },
            { id: 'topProcessPath',  label: 'Top Process',     w: '140px', align: 'left' },
            { id: 'vsAvg',           label: 'vs Avg',          w: '60px',  align: 'right' }
        ];
        return cols.map(function (c) {
            var isSorted = _mgrState.sort.col === c.id;
            var arrow = isSorted ? (_mgrState.sort.dir === 'asc' ? ' ▲' : ' ▼') : '';
            var bg = isSorted ? 'background:#1c2333;' : '';
            return '<th data-mgr-sort="' + c.id + '" style="cursor:pointer;text-align:' + c.align + ';' + bg +
                'padding:6px 8px;position:sticky;top:0;background:#161b22;border-bottom:2px solid #21262d;color:#aaa;font-size:9px;text-transform:uppercase;letter-spacing:.4px;' +
                'min-width:' + c.w + ';" title="Sort by ' + c.label + '">' + escapeHtml(c.label) + arrow + '</th>';
        }).join('');
    }

    function renderMgrRow(r, siteAvg) {
        var isOpen = _mgrState.openManager === r.alias;
        var convColor = r.recordableRate >= 10 ? '#f44336' : r.recordableRate >= 5 ? '#ff9800' : '#4caf50';
        var vsArrow, vsColor;
        if (r.count < 3) { vsArrow = '—'; vsColor = '#666'; }
        else if (r.vsAvg > 2)  { vsArrow = '▲ +' + r.vsAvg; vsColor = '#f44336'; }
        else if (r.vsAvg < -2) { vsArrow = '▼ ' + r.vsAvg;  vsColor = '#4caf50'; }
        else                   { vsArrow = '≈ ' + (r.vsAvg >= 0 ? '+' : '') + r.vsAvg; vsColor = '#888'; }
        var trackChip = r.isTracked ? '<span title="In personnel roster" style="color:#4caf50;font-size:9px;margin-left:4px;">●</span>' : '';

        var html = '<tr data-mgr-row="' + escapeHtml(r.alias) + '" style="cursor:pointer;' + (isOpen ? 'background:#1c2333;' : '') + '">';
        html += '<td style="padding:6px 8px;font-weight:600;color:#64b5f6;">' + escapeHtml(r.alias) + trackChip + '</td>';
        html += '<td style="padding:6px 8px;text-align:right;font-weight:700;">' + r.count + '</td>';
        html += '<td style="padding:6px 8px;text-align:right;color:#f44336;">' + r.recordable + '</td>';
        html += '<td style="padding:6px 8px;text-align:right;color:' + convColor + ';font-weight:700;">' + r.recordableRate + '%</td>';
        html += '<td style="padding:6px 8px;text-align:right;color:#ffb74d;">' + r.nearMiss + '</td>';
        html += '<td style="padding:6px 8px;text-align:right;color:' + (r.severeCount > 0 ? '#e57373' : '#666') + ';">' + r.severeCount + '</td>';
        html += '<td style="padding:6px 8px;text-align:right;color:' + (r.dafw > 0 ? '#e57373' : '#666') + ';">' + r.dafw + '</td>';
        html += '<td style="padding:6px 8px;text-align:right;color:' + (r.rwa > 0 ? '#ffb74d' : '#666') + ';">' + r.rwa + '</td>';
        html += '<td style="padding:6px 8px;text-align:right;color:' + (r.openCount > 0 ? '#ff9800' : '#666') + ';">' + r.openCount + '</td>';
        html += '<td style="padding:6px 8px;font-size:10px;color:#aaa;">' + escapeHtml(formatLabel(r.topBodyPart) || '—') + '</td>';
        html += '<td style="padding:6px 8px;font-size:10px;color:#aaa;">' + escapeHtml(formatLabel(r.topProcessPath) || '—') + '</td>';
        html += '<td style="padding:6px 8px;text-align:right;color:' + vsColor + ';font-weight:700;" title="vs site avg recordable conv. rate (' + siteAvg + '%)">' + vsArrow + '</td>';
        html += '</tr>';

        if (isOpen) {
            html += '<tr><td colspan="12" style="padding:0;background:#0d1117;border-left:3px solid #64b5f6;">' +
                renderManagerDeepDive(r) + '</td></tr>';
        }

        return html;
    }

    // ── Per-manager Deep Dive (v2) ─────────────────────────────
    // Renders a rich panel inside the row's expanded area: 12-week
    // sparkline, severity donut, body part / process path bars,
    // time-of-day grid, open cases panel, full case list.
    function renderManagerDeepDive(r) {
        var h = '<div style="padding:14px;">';

        // Header
        h += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">';
        h += '<div style="font-size:13px;font-weight:700;color:#64b5f6;">👤 ' + escapeHtml(r.alias) + ' — Deep Dive</div>';
        h += '<div style="font-size:10px;color:#888;">' + r.count + ' cases · ' + r.recordable + ' recordable · ' + r.openCount + ' still open</div>';
        h += '</div>';

        // 12-week trend
        var trend = buildWeeklyRecordableTrend(r.cases, 12);
        if (trend.labels.length > 0) {
            h += '<div style="background:#0d1117;border:1px solid #21262d;border-radius:6px;padding:10px;margin-bottom:12px;">' +
                '<div style="font-size:11px;color:#aaa;margin-bottom:6px;">📉 Weekly trend (last 12 weeks)</div>' +
                buildSVGLineChart([
                    { name: 'Cases',       values: trend.recordables.map(function (_, i) { return r.cases.filter(function (c) { var d = new Date(c.incidentDateTime || c.reportedDateTime); return !isNaN(d) && d <= new Date(new Date().getTime() - (11 - i) * 7 * 86400000 + 7 * 86400000) && d > new Date(new Date().getTime() - (11 - i) * 7 * 86400000); }).length; }), color: '#64b5f6' },
                    { name: 'Recordables', values: trend.recordables, color: '#f44336' }
                ], trend.labels, { height: 160 }) +
                '</div>';
        }

        // 3-column grid: severity donut + body parts + process paths
        h += '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:12px;">';

        // Severity / type mix
        h += '<div style="background:#0d1117;border:1px solid #21262d;border-radius:6px;padding:10px;">';
        h += '<div style="font-size:11px;color:#aaa;margin-bottom:6px;">⚠️ Mix</div>';
        h += '<div style="font-size:10px;line-height:1.8;">';
        h += '<div>Recordable: <b style="color:#f44336;">' + r.recordable + '</b> (' + r.recordableRate + '%)</div>';
        h += '<div>Near Miss: <b style="color:#ffb74d;">' + r.nearMiss + '</b></div>';
        h += '<div>Severe (high/critical dx): <b style="color:#e57373;">' + r.severeCount + '</b></div>';
        h += '<div>DAFW active or past: <b style="color:#e57373;">' + r.dafw + '</b></div>';
        h += '<div>RWA active or past: <b style="color:#ffb74d;">' + r.rwa + '</b></div>';
        h += '<div>Open (medical): <b style="color:#ff9800;">' + r.openCount + '</b></div>';
        h += '<div>Last 30d: <b style="color:#64b5f6;">' + r.last30 + '</b></div>';
        h += '</div></div>';

        // Body parts
        h += '<div style="background:#0d1117;border:1px solid #21262d;border-radius:6px;padding:10px;">';
        h += '<div style="font-size:11px;color:#aaa;margin-bottom:6px;">🩹 Body Parts</div>';
        var bpRanked = A.rankCounts(r.bodyParts, 6);
        h += bpRanked.length ? buildSimpleBar(bpRanked, r.count, '#64b5f6') : '<div style="font-size:10px;color:#666;">No body part data</div>';
        h += '</div>';

        // Process paths
        h += '<div style="background:#0d1117;border:1px solid #21262d;border-radius:6px;padding:10px;">';
        h += '<div style="font-size:11px;color:#aaa;margin-bottom:6px;">🛠 Process Paths</div>';
        var ppRanked = A.rankCounts(r.processPaths, 6);
        h += ppRanked.length ? buildSimpleBar(ppRanked, r.count, '#ff9800') : '<div style="font-size:10px;color:#666;">No process path data</div>';
        h += '</div>';

        h += '</div>';

        // Time-of-day grid (7 days × 24 hours)
        h += '<div style="background:#0d1117;border:1px solid #21262d;border-radius:6px;padding:10px;margin-bottom:12px;">';
        h += '<div style="font-size:11px;color:#aaa;margin-bottom:6px;">🕒 When injuries happen (day × hour)</div>';
        h += renderMgrTimeGrid(r.cases);
        h += '</div>';

        // Open cases panel
        var openCases = r.cases.filter(function (c) {
            var med = (c.latestMedicalStatus || '').toLowerCase();
            return med === 'open' || med === 'pending-outside-medical';
        });
        if (openCases.length > 0) {
            h += '<div style="background:#3e2723;border:1px solid #ff9800;border-radius:6px;padding:10px;margin-bottom:12px;">';
            h += '<div style="font-size:11px;color:#ffb74d;margin-bottom:6px;font-weight:700;">🟧 ' + openCases.length + ' open case' + (openCases.length === 1 ? '' : 's') + ' on this team</div>';
            h += '<div style="font-size:10px;color:#e0e0e0;">';
            openCases.slice(0, 5).forEach(function (c) {
                var url = buildIncidentUrl(c);
                var label = (c.caseNumber || '—') + ' · ' + (c.alias || '—') + ' · ' + (c.principalBodyPart || '—');
                h += '<div style="padding:3px 0;border-bottom:1px solid #5d4037;">' +
                    (url ? '<a class="wa-case-link" href="' + url + '" target="_blank">' + escapeHtml(label) + '</a>' : escapeHtml(label)) +
                    ' <span style="color:#ffb74d;">· last FU ' + (c.latestFollowUpDate ? formatDateShort(c.latestFollowUpDate) : 'never') + '</span></div>';
            });
            if (openCases.length > 5) h += '<div style="color:#888;padding:3px 0;">+ ' + (openCases.length - 5) + ' more</div>';
            h += '</div></div>';
        }

        // Full case history table
        h += '<div style="font-size:11px;color:#aaa;margin-bottom:6px;">📋 All ' + r.count + ' cases</div>';
        h += '<div style="max-height:300px;overflow-y:auto;border:1px solid #21262d;border-radius:6px;">';
        h += '<table class="wa-drilldown-table" style="width:100%;font-size:10px;">';
        h += '<thead><tr><th>Case #</th><th>Date</th><th>Type</th><th>Associate</th><th>Body Part</th><th>Process Path</th><th>Recordable</th><th>Status</th></tr></thead><tbody>';
        var sortedCases = r.cases.slice().sort(function (a, b) {
            return new Date(b.incidentDateTime || b.reportedDateTime || 0) - new Date(a.incidentDateTime || a.reportedDateTime || 0);
        });
        sortedCases.forEach(function (c) {
            var url = buildIncidentUrl(c);
            var recColor = c.recordable ? '#f44336' : '#666';
            h += '<tr>';
            h += url ? '<td><a class="wa-case-link" href="' + url + '" target="_blank">' + escapeHtml(c.caseNumber || '—') + '</a></td>' : '<td>' + escapeHtml(c.caseNumber || '—') + '</td>';
            h += '<td>' + (c.incidentDateTime ? formatDateShort(c.incidentDateTime) : '—') + '</td>';
            h += '<td>' + escapeHtml(c.type || '—') + '</td>';
            h += '<td>' + escapeHtml(c.alias || '—') + '</td>';
            h += '<td>' + escapeHtml(formatLabel(c.principalBodyPart) || '—') + '</td>';
            h += '<td>' + escapeHtml(formatLabel(c.incidentProcessPath) || '—') + '</td>';
            h += '<td style="color:' + recColor + ';font-weight:700;">' + (c.recordable ? 'YES' : 'No') + '</td>';
            h += '<td>' + escapeHtml(c.status || '—') + '</td>';
            h += '</tr>';
        });
        h += '</tbody></table></div>';

        h += '</div>';
        return h;
    }

    function renderMgrTimeGrid(cases) {
        var grid = {}; var max = 0;
        for (var d = 0; d < 7; d++) { grid[d] = {}; for (var hr = 0; hr < 24; hr++) grid[d][hr] = 0; }
        cases.forEach(function (c) {
            var dt = c.incidentDateTime;
            if (!dt) return;
            var t = new Date(dt);
            if (isNaN(t)) return;
            var day = t.getDay(), hour = t.getHours();
            grid[day][hour]++;
            if (grid[day][hour] > max) max = grid[day][hour];
        });
        if (max === 0) return '<div style="font-size:10px;color:#666;">No timestamped cases.</div>';

        var dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
        var h = '<table style="width:100%;border-collapse:collapse;font-size:8px;">';
        // Header row: hours
        h += '<tr><th style="padding:2px 4px;"></th>';
        for (var hr2 = 0; hr2 < 24; hr2++) {
            h += '<th style="padding:1px 2px;color:#666;text-align:center;font-weight:400;">' + (hr2 % 6 === 0 ? hr2 : '') + '</th>';
        }
        h += '</tr>';
        for (var dr = 0; dr < 7; dr++) {
            h += '<tr><td style="padding:2px 6px;color:#aaa;font-weight:700;text-align:right;">' + dayNames[dr] + '</td>';
            for (var hr3 = 0; hr3 < 24; hr3++) {
                var v = grid[dr][hr3];
                var intensity = v / max;
                var bg = v === 0 ? '#0d1117' : 'rgba(244,67,54,' + (0.15 + intensity * 0.85).toFixed(2) + ')';
                h += '<td style="padding:0;width:14px;height:14px;background:' + bg + ';border:1px solid #161b22;text-align:center;color:#fff;font-weight:700;" title="' + dayNames[dr] + ' ' + hr3 + ':00 — ' + v + ' case' + (v === 1 ? '' : 's') + '">' + (v > 0 ? v : '') + '</td>';
            }
            h += '</tr>';
        }
        h += '</table>';
        return h;
    }

    // CLAIM FILED SECTION
    // ================================================================
    function renderClaimFiledSection(a) {
        var settings = (WHSLib.state && WHSLib.state.settings) || {};
        if (settings.showAnalyticsClaimFiled === false) return '';
        if (a.claimFiledCases.length === 0) return '';

        var overdueCount = a.claimFiledOverdue.length;
        var body = '';

        // Summary bar
        body += '<div style="display:flex;gap:8px;margin-bottom:10px;">';
        body += '<div style="flex:1;background:#1c2333;border:1px solid #21262d;border-radius:6px;padding:10px;text-align:center;">';
        body += '<div style="font-size:22px;font-weight:bold;color:#64b5f6;">' + a.claimFiledCases.length + '</div>';
        body += '<div style="font-size:9px;color:#888;text-transform:uppercase;margin-top:3px;">Claim Filed</div>';
        body += '</div>';
        body += '<div style="flex:1;background:' + (overdueCount > 0 ? 'linear-gradient(135deg,#3d0000,#5c0a0a)' : '#1c2333') + ';border:' + (overdueCount > 0 ? '2px solid #f4433666' : '1px solid #21262d') + ';border-radius:6px;padding:10px;text-align:center;">';
        body += '<div style="font-size:22px;font-weight:bold;color:' + (overdueCount > 0 ? '#ef5350' : '#4caf50') + ';">' + overdueCount + '</div>';
        body += '<div style="font-size:9px;color:' + (overdueCount > 0 ? '#ef9a9a' : '#a5d6a7') + ';text-transform:uppercase;margin-top:3px;">Follow-up Overdue</div>';
        body += '</div></div>';

        if (overdueCount > 0) {
            body += '<div style="font-size:9px;color:#888;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;">\u26A0\uFE0F Requires Action</div>';
            a.claimFiledOverdue.forEach(function (item) {
                var c = item.case;
                var caseUrl = A.buildIncidentUrl(c);
                var rtwHtml = c.rtwCaseId
                    ? '<a href="https://prod.na.rtw.whs.amazon.dev/placementDetails/' + c.rtwCaseId + '" target="_blank" style="color:#64b5f6;font-size:9px;text-decoration:none;margin-left:6px;">[RTW]</a>'
                    : '';
                body += '<div class="wa-claim-row">';
                body += '<div style="flex:1;min-width:0;">';
                body += '<div style="font-size:10px;font-weight:bold;color:#ef9a9a;">';
                if (caseUrl) {
                    body += '<a href="' + caseUrl + '" target="_blank" class="wa-case-link">' + escapeHtml(c.caseNumber || '') + '</a>';
                } else {
                    body += escapeHtml(c.caseNumber || '');
                }
                body += rtwHtml;
                body += ' \u2014 ' + escapeHtml(c.alias || '') + '</div>';
                body += '<div style="font-size:9px;color:#888;margin-top:1px;">' + escapeHtml(c.principalBodyPart || 'Unknown injury') + (c.incidentProcessPath ? ' \u00B7 ' + escapeHtml(c.incidentProcessPath) : '') + '</div>';
                body += '</div>';
                body += '<div class="wa-claim-days">' + escapeHtml(item.reason) + '</div>';
                body += '</div>';
            });
        }

        if (a.claimFiledCases.length > overdueCount) {
            var compliantCount = a.claimFiledCases.length - overdueCount;
            body += '<div style="font-size:9px;color:#4caf50;margin-top:6px;">\u2705 ' + compliantCount + ' case' + (compliantCount !== 1 ? 's' : '') + ' within 6-day window</div>';
        }

        var badge = overdueCount > 0 ? overdueCount + ' overdue' : 'All current';
        return buildSection('claimfiled', '\uD83D\uDCCB', 'Claim Filed Cases', badge, body, false);
    }

    // ================================================================
    // MASTER RENDER
    // ================================================================
    function renderAllSections(a, prevCounts, container) {
        var html = '';
        html += renderSummary(a, prevCounts);
        html += renderTrendsSection(a);
        html += renderRecordablesDeepDive(a, prevCounts);
        html += renderManagerSection(a, prevCounts);
        if (WHSLib.rir) html += WHSLib.rir.renderRIRSection(a, currentFilters);
        html += renderClaimFiledSection(a);
        html += renderComplianceSection(a);
        html += renderPredictiveSection(a);
        html += renderRiskForecastSection(a);
        html += renderShiftSection(a, prevCounts);
        html += renderHeatmapSection(a);
        html += renderProcessPathSection(a, prevCounts);
        html += renderProcessDeepDiveSection(a);
        html += renderBodyPartSection(a, prevCounts);
        html += renderLocationSection(a, prevCounts);
        html += renderFloorPlanSection(a);
        container.innerHTML = html;
        wireUpInteractions(container, a);
        if (WHSLib.rir) WHSLib.rir.wireRIRButtons();
    }
