    // Role-only quota. Scalar lookup — no more pack/standard branching.
    function getRBIQuota(p) {
        if (!p) return 0;
        var q = RBI_QUOTAS[p.role];
        return (typeof q === 'number') ? q : 0;
    }

    // Note: the `arcCov` parameter is kept for signature compatibility with
    // pre-19.54 callers (the ARC coverage grid still computes per-dept ARC
    // rollup separately). The per-person "Area ARC" pill is gone with
    // sub-dept, so this function no longer reads arcCov.
    function personCompliance(person, inspections, arcCov) {
        var alias = person.alias.toLowerCase();
        var my = inspections.filter(function (i) { return i.assignee === alias && (i.status === 'COMPLETED' || i.status === 'SUBMITTED'); });
        var myRBI = my.filter(function (i) { return i.classification === 'RBI'; });
        // Completion rule (all roles): a *completed/submitted* RBI or ARC counts as
        // done regardless of findings. Both "with findings" and "no findings" are
        // treated as complete. (findingsLoaded is set once the findings fetch resolves
        // for any completed/submitted inspection, independent of finding count.)
        // `my` is already filtered to COMPLETED/SUBMITTED, so every myRBI/myARC entry
        // is a completed inspection. Findings are irrelevant to completion now, and
        // gating on findingsLoaded would undercount inspections whose async findings
        // fetch hasn't resolved yet — so count all completed RBIs/ARCs directly.
        var goodRBI = myRBI;
        var badRBI = [];
        var myARC = my.filter(function (i) { return i.classification === 'ARC'; });
        var goodARC = myARC;
        var rbiQ = getRBIQuota(person);

        return {
            person: person, alias: alias, total: my.length,
            rbiTotal: myRBI.length, rbiCompliant: goodRBI.length, rbiNonCompliant: badRBI.length,
            rbiQuota: rbiQ, rbiMet: goodRBI.length >= rbiQ,
            rbiInspections: myRBI,
            arcTotal: myARC.length, arcCompliant: goodARC.length,
            arcInspections: myARC,
            deptArcCoverage: null,   // legacy field; readers already handle null
            isFullyCompliant: goodRBI.length >= rbiQ,
            findingsPending: my.some(function (i) { return !i.findingsLoaded; })
        };
    }

    // Accepts a Date (legacy week start) OR a range {start, end}.
    function arcCoverage(inspections, wsOrRange) {
        var ws, we;
        if (wsOrRange && wsOrRange.start && wsOrRange.end) {
            ws = wsOrRange.start;
            we = wsOrRange.end;
        } else {
            ws = wsOrRange;
            we = getWeekEnd(ws);
        }
        var now = new Date();
        var isCurrent = ws <= now && now <= we;
        var arcs = inspections.filter(function (i) {
            return i.classification === 'ARC' && (i.status === 'COMPLETED' || i.status === 'SUBMITTED');
        });
        var dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
        var shiftDays = { FHD: [0,1,2,3], FHN: [0,1,2,3], BHD: [3,4,5,6], BHN: [3,4,5,6] };
        var cov = {};

        DEPARTMENTS.forEach(function (dept) {
            cov[dept.id] = {};
            SHIFTS.forEach(function (sh) {
                if (dept.noBHN && sh === 'BHN') { cov[dept.id][sh] = { na: true }; return; }
                var exp = 0;
                shiftDays[sh].forEach(function (dow) {
                    var dd = new Date(ws); dd.setDate(dd.getDate() + dow);
                    if (!isCurrent || dd <= now) exp++;
                });
                cov[dept.id][sh] = { total: 0, compliant: 0, expected: exp, days: {}, daysCovered: 0, inspections: [] };
            });
        });

        arcs.forEach(function (arc) {
            if (!arc.department || !arc.shift) return;
            var shiftsToCredit = [arc.shift];
            var arcDay = new Date(arc.createdAt).getDay();
            if (arcDay === 3) {
                if (arc.shift === 'FHD') shiftsToCredit.push('BHD');
                else if (arc.shift === 'BHD') shiftsToCredit.push('FHD');
                else if (arc.shift === 'FHN') shiftsToCredit.push('BHN');
                else if (arc.shift === 'BHN') shiftsToCredit.push('FHN');
            }
            shiftsToCredit.forEach(function (shift) {
                var cell = cov[arc.department] && cov[arc.department][shift];
                if (!cell || cell.na) return;
                cell.total++;
                cell.inspections.push(arc);
                if (!arc.findingsLoaded || arc.isCompliant) {
                    cell.compliant++;
                    var dn = dayNames[arcDay];
                    cell.days[dn] = (cell.days[dn] || 0) + 1;
                }
            });
        });

        DEPARTMENTS.forEach(function (dept) {
            SHIFTS.forEach(function (sh) {
                var cell = cov[dept.id][sh];
                if (!cell.na) cell.daysCovered = Object.keys(cell.days).length;
            });
        });
        return cov;
    }

    // Accepts a Date (legacy week start) OR a range {start, end}.
    function weeklySummary(inspections, wsOrRange) {
        var range = (wsOrRange && wsOrRange.start && wsOrRange.end) ? wsOrRange :
                    { start: wsOrRange, end: getWeekEnd(wsOrRange), mode: 'thisWeek' };
        var cov = arcCoverage(inspections, range);
        var pResults = _config.personnel.map(function (p) { return personCompliance(p, inspections, cov); });
        var tracked = {};
        _config.personnel.forEach(function (p) { tracked[p.alias.toLowerCase()] = true; });
        var untrackedMap = {};
        inspections.forEach(function (i) {
            if (i.assignee && !tracked[i.assignee]) {
                if (!untrackedMap[i.assignee]) untrackedMap[i.assignee] = { alias: i.assignee, rbi: 0, arc: 0, other: 0, total: 0 };
                untrackedMap[i.assignee].total++;
                if (i.classification === 'RBI') untrackedMap[i.assignee].rbi++;
                else if (i.classification === 'ARC') untrackedMap[i.assignee].arc++;
                else untrackedMap[i.assignee].other++;
            }
        });
        var untracked = Object.keys(untrackedMap).map(function (k) { return untrackedMap[k]; }).sort(function (a, b) { return b.total - a.total; });

        var tRBI = 0, tARC = 0, gRBI = 0, gARC = 0, tFind = 0, pMet = 0;
        inspections.forEach(function (i) {
            if (i.classification === 'RBI') { tRBI++; if (i.findingsLoaded && i.isCompliant) gRBI++; }
            if (i.classification === 'ARC') { tARC++; if (i.findingsLoaded && i.isCompliant) gARC++; }
            if (i.findingsCount) tFind += i.findingsCount;
        });
        pResults.forEach(function (pr) { if (pr.isFullyCompliant) pMet++; });

        var covCells = 0, covMet = 0;
        DEPARTMENTS.forEach(function (dept) {
            SHIFTS.forEach(function (sh) {
                var c = cov[dept.id][sh];
                if (c.na) return;
                covCells++;
                if (c.expected === 0 || c.daysCovered >= c.expected) covMet++;
            });
        });

        return {
            weekLabel: formatRange(range),
            range: range,
            inspections: inspections,
            totalInspections: inspections.length, totalRBIs: tRBI, totalARCs: tARC,
            compliantRBIs: gRBI, compliantARCs: gARC, totalFindings: tFind,
            personResults: pResults, peopleMet: pMet, peopleTotal: pResults.length,
            arcCoverage: cov, covCells: covCells, covMet: covMet,
            untracked: untracked,
            findingsPending: inspections.some(function (i) {
                return (i.classification === 'RBI' || i.classification === 'ARC') &&
                    (i.status === 'COMPLETED' || i.status === 'SUBMITTED') && !i.findingsLoaded;
            })
        };
    }

