    function fmtDate(s) { if (!s) return '\u2014'; try { var d = new Date(s); return isNaN(d) ? s : d.toLocaleDateString('en-US',{month:'short',day:'numeric'}); } catch(e) { return s; } }
    function fmtDateTime(s) { if (!s) return '\u2014'; try { var d = new Date(s); return isNaN(d) ? s : d.toLocaleDateString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',hour12:true}); } catch(e) { return s; } }
    function pct(n,t) { return t ? Math.round(n/t*100)+'%' : '0%'; }
