        html += '<div style="max-height:250px;overflow-y:auto;scrollbar-width:thin;"><table class="rt-tbl" style="width:100%;"><thead><tr><th>Area</th><th>Assignee</th><th>Shift</th><th>Findings</th><th>Date</th></tr></thead><tbody>';

