    // ================================================================
    // FCLM STATUS FETCH (live, works cross-domain via GM_xmlhttpRequest)
    // ================================================================
    var _fclmCache = {};
    var FCLM_TTL = 5 * 60 * 1000;

    function fetchFCLMStatus(alias, callback) {
        var now = Date.now();
        var cached = _fclmCache[alias];
        if (cached && (now - cached.ts) < FCLM_TTL) {
            callback(cached.result);
            return;
        }

        // Route through the proper FCLM helper. Previously this function rolled
        // its own regex parsing of FCLM HTML (which broke against the current
        // markup) — causing "everyone is offsite" and labor-track paths never
        // showing in the Pin panel.
        if (lib.fclm && lib.fclm.checkClockStatus) {
            lib.fclm.checkClockStatus(alias).then(function (cs) {
                var result = {
                    onsite:    !!cs.isClockedIn,
                    path:      cs.path || null,
                    shiftCode: cs.shiftCode || null,
                    badge:     cs.badge || null,
                    fetchedAt: Date.now(),
                    error:     cs.pageLoaded ? null : 'FCLM page not loaded'
                };
                _fclmCache[alias] = { result: result, ts: Date.now() };
                callback(result);
            }).catch(function (e) {
                var result = { onsite: null, path: null, fetchedAt: Date.now(), error: (e && e.message) || 'fclm error' };
                _fclmCache[alias] = { result: result, ts: Date.now() };
                callback(result);
            });
            return;
        }

        // Fallback to raw FCLM fetch if the proper helper hasn't loaded yet.
        GM_xmlhttpRequest({
            method: 'GET',
            url: FCLM_BASE + alias,
            headers: { 'Accept': 'text/html' },
            onload: function (r) {
                var result = { onsite: false, path: null, fetchedAt: Date.now(), error: null };
                if (r.status === 200) {
                    try {
                        var h = r.responseText;
                        var on = h.indexOf('on-clock') !== -1;
                        var off = h.indexOf('off-clock') !== -1;
                        if (on || off) {
                            result.onsite = h.lastIndexOf('on-clock') > h.lastIndexOf('off-clock');
                        }
                    } catch (e) { result.error = e.message; }
                } else {
                    result.error = 'HTTP ' + r.status;
                }
                _fclmCache[alias] = { result: result, ts: Date.now() };
                callback(result);
            },
            onerror: function () {
                var result = { onsite: null, path: null, fetchedAt: Date.now(), error: 'Network error' };
                _fclmCache[alias] = { result: result, ts: Date.now() };
                callback(result);
            }
        });
    }

