// ================================================================
// WHS Incident Tools — Shared Library — Part 11A
// RTW Integration — Token Harvesting + API Core
// ================================================================

(function () {
    'use strict';

    var lib = window.WHSLib;
    if (!lib) { console.error('WHSLib not loaded'); return; }
    if (lib.rtw) return;

    var RTW_API       = 'https://prod.na.rtw-api.whs.amazon.dev';
    var RTW_PORTAL    = 'https://prod.na.rtw.whs.amazon.dev';
    var RTW_TOKEN_KEY = 'whs_rtw_token';
    var RTW_TOKEN_TS  = 'whs_rtw_token_ts';
    var RTW_SITE_KEY  = 'whs_rtw_site_id';
    var TOKEN_TTL     = 45 * 60 * 1000; // 45 min (Cognito tokens last 1hr, refresh early)
    var CACHE_TTL     = 15 * 60 * 1000;

    var _detailCache  = {};
    var _siteCache    = null;
    var _openCache    = null;
    var _openCacheTs  = 0;

    // ================================================================
    // TOKEN MANAGEMENT
    // ================================================================

    // Called when running ON the RTW domain — harvest and store token.
    // If running in a harvest popup (?whs_harvest=1), shows progress UI and
    // polls localStorage until the token appears (up to 90s). This fixes the
    // "popup opens but token never captured" case where the page wasn't done
    // authenticating when harvest ran.
    function harvestRTWToken() {
        var isHarvestPopup = false;
        try { isHarvestPopup = window.location.search.indexOf('whs_harvest=1') !== -1; } catch (e) {}

        function _readToken() {
            try {
                var t = localStorage.getItem('token');
                if (t && t.indexOf('eyJ') === 0) return t;
            } catch (e) {}
            return null;
        }
        function _storeAndNotify(token) {
            if (typeof GM_setValue === 'function') {
                GM_setValue(RTW_TOKEN_KEY, token);
                GM_setValue(RTW_TOKEN_TS, String(Date.now()));
            }
            console.log('[WHS RTW] Token harvested and stored');
            if (window.opener) {
                try { window.opener.postMessage({ type: 'WHS_RTW_TOKEN', token: token }, '*'); } catch (pe) {}
            }
        }
        function _paintBanner() {
            if (document.getElementById('whs-rtw-auth-banner')) return;
            var b = document.createElement('div');
            b.id = 'whs-rtw-auth-banner';
            b.style.cssText = 'position:fixed;top:0;left:0;right:0;background:linear-gradient(135deg,#1976d2,#0d47a1);color:#fff;padding:14px 20px;font-family:"Segoe UI",Arial,sans-serif;font-size:14px;z-index:2147483647;box-shadow:0 4px 12px rgba(0,0,0,.4);text-align:center;';
            b.innerHTML = '<div style="font-weight:bold;margin-bottom:4px;">🔑 WHS RTW — Authenticating</div><div id="whs-rtw-auth-status" style="font-size:12px;color:#bbdefb;">Waiting for login... If you\'re prompted, please sign in. This window will close automatically.</div>';
            if (document.body) document.body.appendChild(b);
        }
        function _setStatus(msg) {
            var el = document.getElementById('whs-rtw-auth-status');
            if (el) el.textContent = msg;
        }

        // Fast path: token is already there (page was authenticated when we landed)
        var token = _readToken();
        if (token) {
            _storeAndNotify(token);
            if (isHarvestPopup) setTimeout(function () { try { window.close(); } catch (e) {} }, 300);
            return token;
        }

        // Slow path: only relevant in harvest popups — show UI and poll
        if (!isHarvestPopup) return null;

        if (document.body) _paintBanner();
        else document.addEventListener('DOMContentLoaded', _paintBanner);

        var elapsed = 0;
        var INTERVAL = 500;
        var MAX = 90000;
        var poll = setInterval(function () {
            elapsed += INTERVAL;
            _paintBanner();
            var t = _readToken();
            if (t) {
                _storeAndNotify(t);
                _setStatus('✓ Token captured! Closing window...');
                clearInterval(poll);
                setTimeout(function () { try { window.close(); } catch (e) {} }, 600);
                return;
            }
            if (elapsed >= MAX) {
                _setStatus('⏱ Timed out waiting for login. Please sign in, then close this tab and click Get RTW Token again.');
                clearInterval(poll);
            }
        }, INTERVAL);
        return null;
    }

    function ensureRTWToken(callback) {
        if (isTokenFresh()) { return callback(getRTWToken()); }

        // Queue concurrent callers so only one tab opens
        if (ensureRTWToken._pending) { ensureRTWToken._queue.push(callback); return; }
        ensureRTWToken._pending = true;

        var tab = window.open(RTW_PORTAL + '/?whs_harvest=1', '_blank');
        var elapsed = 0;
        var POLL_MS = 750;
        // Wait up to 95s — gives the popup time to show its login prompt and
        // the user time to sign in. Previous 25s timeout was the main cause
        // of "popup opens but token never captured" reports.
        var MAX_MS  = 95000;

        // Record the token timestamp before opening so we can detect a NEW token
        var prevTs = 0;
        try { prevTs = parseInt(typeof GM_getValue === 'function' ? GM_getValue(RTW_TOKEN_TS, '0') : '0', 10); } catch(e) {}

        function done(token) {
            clearInterval(pollTimer);
            ensureRTWToken._pending = false;
            // postMessage bridge still works if opener survived (fast path)
            window.removeEventListener('message', onMsg);
            if (tab) { try { tab.close(); } catch (e) {} }
            callback(token);
            var q = ensureRTWToken._queue.splice(0);
            for (var i = 0; i < q.length; i++) { try { q[i](token); } catch (e) {} }
        }

        // Poll GM storage for a freshly written token
        var pollTimer = setInterval(function () {
            elapsed += POLL_MS;
            try {
                var ts = parseInt(typeof GM_getValue === 'function' ? GM_getValue(RTW_TOKEN_TS, '0') : '0', 10);
                if (ts > prevTs && (Date.now() - ts) < TOKEN_TTL) {
                    var tok = typeof GM_getValue === 'function' ? GM_getValue(RTW_TOKEN_KEY, null) : null;
                    if (tok) { done(tok); return; }
                }
            } catch (e) {}
            if (elapsed >= MAX_MS) {
                console.warn('[WHS RTW] Token harvest timed out after ' + MAX_MS + 'ms');
                done(null);
            }
        }, POLL_MS);

        // postMessage fast path â€” fires if window.opener survived the RTW redirect
        function onMsg(e) {
            if (!e.data || e.data.type !== 'WHS_RTW_TOKEN') return;
            done(e.data.token);
        }
        window.addEventListener('message', onMsg);
    }
    ensureRTWToken._pending = false;
    ensureRTWToken._queue   = [];

    // Called from Austin domain — retrieve stored token
    function getRTWToken() {
        try {
            if (typeof GM_getValue !== 'function') return null;
            var ts = parseInt(GM_getValue(RTW_TOKEN_TS, '0'), 10);
            if (Date.now() - ts > TOKEN_TTL) {
                console.warn('[WHS RTW] Token expired — open RTW portal to refresh');
                return null;
            }
            var token = GM_getValue(RTW_TOKEN_KEY, null);
            return token || null;
        } catch (e) {
            return null;
        }
    }

    function isTokenFresh() {
        try {
            if (typeof GM_getValue !== 'function') return false;
            var ts = parseInt(GM_getValue(RTW_TOKEN_TS, '0'), 10);
            return (Date.now() - ts) < TOKEN_TTL;
        } catch (e) { return false; }
    }

    // ================================================================
    // CORE API REQUEST (uses GM_xmlhttpRequest to bypass CORS)
    // ================================================================

    function rtwRequest(path, callback) {
        var token = getRTWToken();
        if (!token) {
            callback(null, 'NO_TOKEN');
            return;
        }

        GM_xmlhttpRequest({
            method:  'GET',
            url:     RTW_API + path,
            headers: {
                'Authorization': 'Bearer ' + token,
                'Accept':        'application/json',
                'Content-Type':  'application/json'
            },
            timeout: 15000,
            onload: function (r) {
                if (r.status === 200) {
                    try {
                        callback(JSON.parse(r.responseText), null);
                    } catch (e) {
                        callback(null, 'Parse error: ' + e.message);
                    }
                } else if (r.status === 401 || r.status === 403) {
                    callback(null, 'TOKEN_EXPIRED');
                } else {
                    callback(null, 'HTTP ' + r.status);
                }
            },
            onerror:   function () { callback(null, 'Network error'); },
            ontimeout: function () { callback(null, 'Timeout'); }
        });
    }

    // ================================================================
    // SITE ID RESOLUTION
    // ================================================================

    // Resolves site name (e.g. "IND5") to numeric site ID
    function resolveSiteId(callback) {
        if (_siteCache) { callback(_siteCache, null); return; }

        // Try stored value first
        try {
            if (typeof GM_getValue === 'function') {
                var stored = GM_getValue(RTW_SITE_KEY, null);
                if (stored) {
                    _siteCache = JSON.parse(stored);
                    callback(_siteCache, null);
                    return;
                }
            }
        } catch (e) {}

        // If we have a site code in settings, fetch only that site directly
        var knownSiteCode = lib.state.settings && lib.state.settings.siteCode;
        var apiPath = knownSiteCode
            ? '/sites/allowed'
            : '/sites/allowed';

        rtwRequest(apiPath, function (data, err) {
            if (err || !data || !data.length) {
                callback(null, err || 'No sites returned');
                return;
            }

            var siteCode = lib.state.settings && lib.state.settings.siteCode;
            var match = null;

            if (siteCode) {
                for (var i = 0; i < data.length; i++) {
                    if (data[i].site === siteCode) { match = data[i]; break; }
                }
            }

            // Fall back to first allowed site
            if (!match) match = data[0];

            _siteCache = match;
            try {
                if (typeof GM_setValue === 'function') {
                    GM_setValue(RTW_SITE_KEY, JSON.stringify(match));
                }
            } catch (e) {}

            callback(match, null);
        });
    }

    // ================================================================
    // FETCH ACCOMMODATION DETAIL (per-case)
    // ================================================================

    function fetchAccommodationDetail(rtwCaseId, callback) {
        if (!rtwCaseId) { callback(null, 'No RTW case ID'); return; }

        var cached = _detailCache[rtwCaseId];
        if (cached && (Date.now() - cached.ts) < CACHE_TTL) {
            callback(cached.data, null);
            return;
        }

        rtwRequest('/accommodation/' + rtwCaseId, function (data, err) {
            if (data) {
                _detailCache[rtwCaseId] = { data: data, ts: Date.now() };
            }
            callback(data, err);
        });
    }

    // ================================================================
    // FETCH ALL OPEN ACCOMMODATIONS (site-wide)
    // ================================================================

    function fetchOpenAccommodations(callback) {
        if (_openCache && (Date.now() - _openCacheTs) < CACHE_TTL) {
            callback(_openCache, null);
            return;
        }

        resolveSiteId(function (site, err) {
            if (err || !site) { callback(null, err || 'Could not resolve site'); return; }

            rtwRequest('/accommodation/open/site/' + site.id, function (data, err2) {
                if (data) {
                    data = data.filter(function (d) { return d.accommodationType === 'AUSTIN'; });
                    _openCache   = data;
                    _openCacheTs = Date.now();
                }
                callback(data, err2);
            });
        });
    }

    // ================================================================
    // DATA PARSERS / HELPERS
    // ================================================================

    function parseAccommodationDetail(d) {
        if (!d) return null;

        var jobs = (d.allocatedJobShifts || []).map(function (j) {
            return {
                jobName:        (j.job && j.job.name) || j.jobName || 'Unknown',
                jobType:        (j.job && j.job.jobType && j.job.jobType.name) || '',
                shiftCode:      (j.shift && j.shift.shiftCode) || '',
                allocatedHours: j.allocatedHours || null
            };
        });

        var restrictions = (d.workRestrictions || []).map(function (r) {
            return {
                task:          r.restrictionTaskName || (r.task && r.task.label) || '',
                hours:         r.hoursRestricted || null,
                bodyLocation:  r.bodyLocation || null,
                yesNo:         r.yesNoRestriction || false
            };
        });

        var now       = Date.now();
        var endDate   = d.endAt ? new Date(d.endAt) : null;
        var startDate = d.startAt ? new Date(d.startAt) : null;
        var daysLeft  = endDate ? Math.ceil((endDate - now) / 86400000) : null;
        var daysIn    = startDate ? Math.floor((now - startDate) / 86400000) : null;

        return {
            id:                 d.id,
            login:              d.login || '',
            associateFullName:  d.associateFullName || '',
            employeeId:         d.employeeId || '',
            status:             (d.accommodationStatus && d.accommodationStatus.status) || d.status || 'Unknown',
            accommodationType:  d.accommodationType || '',
            shiftCode:          d.shiftCode || '',
            job:                d.job || '',
            managerFullName:    d.managerFullName || '',
            managerAlias:       d.managerAlias || '',
            startAt:            d.startAt || null,
            endAt:              d.endAt || null,
            daysLeft:           daysLeft,
            daysIn:             daysIn,
            normalShiftLength:  d.normalShiftLength || null,
            modifiedShiftLength: d.modifiedShiftLength || null,
            weeklyLimitedHours: d.weeklyLimitedHours || null,
            canWorkNormalHours: d.canWorkNormalShiftHours || false,
            canWorkOver40:      d.canWorkMoreThan40Hours || false,
            customNotes:        d.customNotes || null,
            decisionNotes:      d.decisionNotes || null,
            requesterLogin:     d.requesterLogin || '',
            decisionByLogin:    d.decisionByLogin || '',
            externalCaseId:     d.externalCaseId || '',
            decisionAt:         d.decisionAt || null,
            jobs:               jobs,
            restrictions:       restrictions,
            closedAt:           d.closedAt || null,
            isExpiringSoon:     daysLeft !== null && daysLeft >= 0 && daysLeft <= 14,
            isExpired:          daysLeft !== null && daysLeft < 0,
            isIndefinite:       endDate && endDate.getFullYear() >= 2999
        };
    }

    function parseOpenAccommodation(d) {
        if (!d) return null;
        var now      = Date.now();
        var endDate  = d.endAtDate ? new Date(d.endAtDate) : null;
        var startDate = d.startAtDate ? new Date(d.startAtDate) : null;
        var daysLeft = endDate ? Math.ceil((endDate - now) / 86400000) : null;

        return {
            id:               d.id,
            login:            d.login || '',
            associateFullName: d.associateFullName || '',
            accommodationType: d.accommodationType || '',
            status:           (d.accommodationStatusCategory && d.accommodationStatusCategory.status) || '',
            category:         (d.accommodationStatusCategory && d.accommodationStatusCategory.category) || '',
            daysInCategory:   (d.accommodationStatusCategory && d.accommodationStatusCategory.daysInCategory) || 0,
            closenessToExpiration: (d.accommodationStatusCategory && d.accommodationStatusCategory.closenessToExpiration) || '',
            startAtDate:      d.startAtDate || null,
            endAtDate:        d.endAtDate || null,
            daysLeft:         daysLeft,
            shiftCode:        d.shiftCode || '',
            caseId:           (d.caseId || '').trim(),
            requesterLogin:   d.requesterLogin || '',
            totalDays:        d.totalAccommodatedDaysByAssociate || 0,
            // Manager info — exposed here (previously only parseDetail read it)
            // so the TLD Dashboard can group by manager without an N-way
            // fetch-detail call per record. Field names vary in the raw
            // payload (`managerAlias`, `managerLogin`, `manager.login`) —
            // check all three defensively.
            managerAlias:     d.managerAlias || d.managerLogin || (d.manager && d.manager.login) || '',
            managerFullName:  d.managerFullName || (d.manager && d.manager.fullName) || '',
            jobs:             (d.allocatedJobShifts || []).map(function (j) {
                return {
                    jobName:   j.jobName || '',
                    jobType:   j.jobType || '',
                    hours:     j.allocatedHours || null
                };
            }),
            isExpiringSoon:   daysLeft !== null && daysLeft >= 0 && daysLeft <= 14,
            isExpired:        daysLeft !== null && daysLeft < 0,
            isIndefinite:     endDate && endDate.getFullYear() >= 2999
        };
    }

    function invalidateDetailCache(rtwCaseId) {
        if (rtwCaseId) delete _detailCache[rtwCaseId];
        else _detailCache = {};
    }

    function invalidateSiteCache() {
        _openCache   = null;
        _openCacheTs = 0;
    }

    // ================================================================
    // EXPOSE lib.rtw (core)
    // ================================================================

    lib.rtw = {
        harvestToken:              harvestRTWToken,
        ensureToken:               ensureRTWToken,
        getToken:                  getRTWToken,
        isTokenFresh:              isTokenFresh,
        request:                   rtwRequest,
        resolveSiteId:             resolveSiteId,
        fetchDetail:               fetchAccommodationDetail,
        fetchOpen:                 fetchOpenAccommodations,
        parseDetail:               parseAccommodationDetail,
        parseOpen:                 parseOpenAccommodation,
        invalidateDetailCache:     invalidateDetailCache,
        invalidateSiteCache:       invalidateSiteCache,
        RTW_PORTAL:                RTW_PORTAL
    };

    // Pre-seed site cache from GM storage at module init (avoids /sites/allowed call)
    try {
        if (typeof GM_getValue === 'function') {
            var _storedSite = GM_getValue(RTW_SITE_KEY, null);
            if (_storedSite) _siteCache = JSON.parse(_storedSite);
        }
    } catch (e) {}

    // If we're ON the RTW domain, harvest the token. RTW's React app writes
    // the token to localStorage asynchronously after SSO completes, so one
    // attempt at document-idle often misses it. Poll for up to ~30s.
    if (window.location.hostname.indexOf('rtw.whs.amazon.dev') !== -1) {
        var initialToken = harvestRTWToken();
        if (!initialToken) {
            var harvestAttempts = 0;
            var harvestTimer = setInterval(function () {
                harvestAttempts++;
                var t = harvestRTWToken();
                if (t || harvestAttempts >= 40) {
                    clearInterval(harvestTimer);
                    if (t) console.log('[WHS RTW] Token harvested after ' + (harvestAttempts * 750) + 'ms');
                }
            }, 750);
        }
        console.log('[WHS RTW] Running on RTW domain — token harvester active');
    }

    console.log('WHSLib Part 11A loaded: RTW Token + API Core');

})();

