            try { var t2=Date.now(); var d3=await H.apiPost(EP.premise,{site:site,module:testMod}); var a3=H.findArray(d3); if(a3){var counts={};a3.forEach(function(i){var st=String(i.status||'?');counts[st]=(counts[st]||0)+1;});res.push({ok:true,text:'on-premise ('+testMod+'): '+(Date.now()-t2)+'ms \u2014 '+Object.entries(counts).map(function(e){return e[0]+':'+e[1];}).join(', ')});} } catch(e){res.push({ok:false,text:'on-premise: '+e.message});}
            diag.innerHTML = res.map(function(r){return '<div style="color:'+(r.ok?'#4caf50':'#f44336')+';font-family:monospace;font-size:9px;white-space:pre-wrap;">'+(r.ok?'[OK]':'[ERR]')+' '+esc(r.text)+'</div>';}).join('');
