    // ── Settings ───────────────────────────────────────────────────
    // Bot token cross-panel fallback: users can set the Safety Tracker
    // bot token in THREE places — the old ASR settings modal
    // (`asr_botToken`), the unified 🤖 Slack Bot panel (also
    // `asr_botToken`), OR Huddle Settings (`hud.botToken` inside its own
    // config blob). Prior versions only read `asr_botToken`, so a user
    // who'd set the token in Huddle Settings but never in the ASR/Slack
    // Bot panels would click "Send Reminders" and get bounced straight
    // to the config modal even though the token existed. Now we defer
    // to `lib.slackBot.getCreds()` which walks all three sources.
    function _resolveBotToken() {
        var direct = GM_getValue('asr_botToken', '');
        if (direct) return direct;
        try {
            if (lib.slackBot && lib.slackBot.getCreds) {
                var c = lib.slackBot.getCreds();
                return (c && c.botToken) || '';
            }
        } catch (e) {}
        return '';
    }
    function getSettings() {
        return {
            botToken:          _resolveBotToken(),
            linkTemplate:      GM_getValue('asr_linkTemplate', CFG.TASK_LINK_TEMPLATE),
            myAlias:           GM_getValue('asr_myAlias', ''),
            ccAliases:         GM_getValue('asr_ccAliases', 'devajami'),
            userMap:           GM_getValue('asr_userMap', {}),
            rbiUserMap:        GM_getValue('asr_rbiUserMap', {}),
            cooldownEnabled:   GM_getValue('asr_cooldownEnabled', true),
            summaryChannelId:  GM_getValue('asr_summaryChannelId', ''),
        };
    }

    function saveSettings(s) {
        GM_setValue('asr_botToken', s.botToken || '');
        GM_setValue('asr_linkTemplate', s.linkTemplate || CFG.TASK_LINK_TEMPLATE);
        GM_setValue('asr_myAlias', s.myAlias || '');
        GM_setValue('asr_ccAliases', s.ccAliases || '');
        if (s.userMap) GM_setValue('asr_userMap', s.userMap);
        if (s.rbiUserMap) GM_setValue('asr_rbiUserMap', s.rbiUserMap);
        GM_setValue('asr_cooldownEnabled', s.cooldownEnabled !== false);
        GM_setValue('asr_summaryChannelId', s.summaryChannelId || '');
    }

    // Migrate old link template if needed
    (function () {
        var old = GM_getValue('asr_linkTemplate', '');
        if (old && old.indexOf('/inspections/') !== -1) GM_setValue('asr_linkTemplate', CFG.TASK_LINK_TEMPLATE);
    })();

    // ── Dedup Tracking ─────────────────────────────────────────────
    function getDedupLog() { return GM_getValue('asr_dedupLog', {}); }
    function todayKey() { return new Date().toISOString().slice(0, 10); }

    function getDedupStatus(prefix) {
        prefix = prefix || 'task';
        var settings = getSettings();
        var log = getDedupLog();
        var key = prefix + '_' + todayKey();
        var today = log[key] || { sends: [] };
        var count = today.sends.length;
        var lastSend = count > 0 ? today.sends[count - 1] : null;
        var hoursSinceLast = lastSend ? (Date.now() - lastSend.timestamp) / 3600000 : Infinity;

        if (settings.cooldownEnabled) {
            if (count >= CFG.MAX_SENDS_PER_DAY)
                return { allowed: false, count: count, reason: 'Daily limit reached (2/2 sent)' };
            if (count > 0 && hoursSinceLast < CFG.MIN_HOURS_BETWEEN) {
                var minsLeft = Math.ceil((CFG.MIN_HOURS_BETWEEN - hoursSinceLast) * 60);
                return { allowed: false, count: count, reason: 'Must wait ' + minsLeft + ' more min before next send' };
            }
            return { allowed: true, count: count, reason: count === 0 ? '1st reminder today' : '2nd (final) reminder today' };
        }
        return { allowed: true, count: count, reason: 'Cooldown off \u2014 ' + count + ' sent today' };
    }

    function recordSend(prefix, ids) {
        var log = getDedupLog();
        var key = (prefix || 'task') + '_' + todayKey();
        if (!log[key]) log[key] = { sends: [] };
        log[key].sends.push({ timestamp: Date.now(), items: ids });
        var cutoff = new Date(); cutoff.setDate(cutoff.getDate() - 7);
        var cutoffStr = cutoff.toISOString().slice(0, 10);
        Object.keys(log).forEach(function (k) {
            if (k.split('_').pop() < cutoffStr) delete log[k];
        });
        GM_setValue('asr_dedupLog', log);
    }

    // ── DOM Helpers ────────────────────────────────────────────────
    function waitFor(predicate, timeout, interval) {
        timeout = timeout || 8000; interval = interval || 150;
        return new Promise(function (resolve, reject) {
            var start = Date.now();
            var check = function () {
                var result = predicate();
                if (result) return resolve(result);
                if (Date.now() - start > timeout) return reject(new Error('waitFor timeout'));
                setTimeout(check, interval);
            };
            check();
        });
    }
    function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

    function isolateOverlay(overlay) {
        var stopBubble = function (e) { e.stopPropagation(); };
        ['keydown','keyup','keypress','input','mousedown','mouseup','click','pointerdown','pointerup']
            .forEach(function (evt) { overlay.addEventListener(evt, stopBubble, false); });
        var blockFocusTrap = function (e) { if (overlay.contains(e.target)) e.stopImmediatePropagation(); };
        ['focusin','focusout','focus','blur']
            .forEach(function (evt) { document.addEventListener(evt, blockFocusTrap, true); });
        var blockKeyTrap = function (e) { if (overlay.contains(e.target)) e.stopImmediatePropagation(); };
        document.addEventListener('keydown', blockKeyTrap, true);
        var cleanup = function () {
            ['focusin','focusout','focus','blur']
                .forEach(function (evt) { document.removeEventListener(evt, blockFocusTrap, true); });
            document.removeEventListener('keydown', blockKeyTrap, true);
        };
        overlay._asrCleanup = cleanup;
        var mo = new MutationObserver(function () {
            if (!document.body.contains(overlay)) { cleanup(); mo.disconnect(); }
        });
        mo.observe(document.body, { childList: true, subtree: false });
    }
    function removeOverlay(overlay) {
        if (overlay._asrCleanup) overlay._asrCleanup();
        overlay.remove();
    }

    // ── Slack API ──────────────────────────────────────────────────
    function slackAPI(method, params) {
        var settings = getSettings();
        return new Promise(function (resolve, reject) {
            GM_xmlhttpRequest({
                method: 'POST', url: CFG.SLACK_API + '/' + method,
                headers: { 'Authorization': 'Bearer ' + settings.botToken, 'Content-Type': 'application/json; charset=utf-8' },
                data: JSON.stringify(params),
                onload: function (res) {
                    try {
                        var data = JSON.parse(res.responseText);
                        if (data.ok) { resolve(data); return; }
                        // Slack returns { ok:false, error:'missing_scope', needed:'X', provided:'Y' }
                        // for scope errors — surface the `needed` field so the user
                        // knows what to add to their bot install.
                        var msg = data.error || 'Slack API error';
                        // Both `missing_scope` (for chat:write.public) AND
                        // `not_in_channel` mean the same thing in practice for
                        // this shared bot: the bot isn't a member of the target
                        // channel. Scopes on the shared Safety Tracker bot are fixed by
                        // policy — the ONLY user-actionable fix is to invite
                        // the bot to the channel from within Slack.
                        if (data.error === 'missing_scope' || data.error === 'not_in_channel') {
                            msg = data.error + ' — the Safety Tracker bot needs to be added to your target channel. In Slack, open the channel and type "/add Safety Tracker" (case-sensitive), then retry. The shared bot\'s OAuth scopes are fixed and cannot be changed.';
                        } else if (data.error === 'channel_not_found') {
                            msg = 'channel_not_found — the channel ID in your Slack Bot settings doesn\'t exist or the bot can\'t see it. Verify the ID (right-click the channel in Slack → "View channel details" → scroll to the bottom for the ID).';
                        } else if (data.error === 'invalid_auth' || data.error === 'not_authed') {
                            msg = data.error + ' — bot token in your Slack Bot settings is wrong or expired. Grab the current token from your admin and re-paste it.';
                        } else if (data.error === 'token_revoked') {
                            msg = 'token_revoked — the shared bot token was revoked. Contact SMABRADE (admin) to get the new one.';
                        } else if (data.error === 'ratelimited') {
                            msg = 'ratelimited — Slack throttled us. Wait a minute and retry.';
                        }
                        reject(new Error(msg));
                    }
                    catch (e) { reject(e); }
                },
                onerror: function () { reject(new Error('Network error contacting Slack')); },
            });
        });
    }
    async function sendGroupDM(slackUserIds, messageText) {
        var conv = await slackAPI('conversations.open', { users: slackUserIds.join(',') });
        await slackAPI('chat.postMessage', { channel: conv.channel.id, text: messageText, unfurl_links: false });
        return conv.channel.id;
    }
    async function postToChannel(channelId, messageText) {
        // link_names: true so <@UID> mentions trigger notifications
        await slackAPI('chat.postMessage', { channel: channelId, text: messageText, unfurl_links: false, link_names: true });
    }

    // ── files.uploadV2 — three-step external file upload ───────────
    // Token requires `files:write` scope on the bot.
    function _slackForm(method, params) {
        var settings = getSettings();
        var token = settings.botToken;
        if (!token) return Promise.reject(new Error('No Slack bot token'));
        var body = Object.keys(params || {}).map(function (k) {
            return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]);
        }).join('&');
        return new Promise(function (resolve, reject) {
            GM_xmlhttpRequest({
                method: 'POST',
                url: 'https://slack.com/api/' + method,
                headers: {
                    'Authorization': 'Bearer ' + token,
                    'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8'
                },
                data: body,
                onload: function (r) {
                    try { resolve(JSON.parse(r.responseText)); }
                    catch (e) { reject(new Error('Slack ' + method + ' bad JSON')); }
                },
                onerror: function () { reject(new Error('Slack ' + method + ' network error')); }
            });
        });
    }

    function _slackPutBytes(uploadUrl, blob) {
        return new Promise(function (resolve, reject) {
            var fd = new FormData();
            fd.append('file', blob);
            GM_xmlhttpRequest({
                method: 'POST',
                url: uploadUrl,
                data: fd,
                onload: function (r) {
                    if (r.status >= 200 && r.status < 300) resolve();
                    else reject(new Error('upload failed: HTTP ' + r.status));
                },
                onerror: function () { reject(new Error('upload network error')); }
            });
        });
    }

    async function uploadFileToChannel(channelId, blob, filename, title, initialComment) {
        if (!channelId) throw new Error('no channel id');
        if (!blob) throw new Error('no blob');
        // Step 1: getUploadURLExternal
        var step1 = await _slackForm('files.getUploadURLExternal', {
            filename: filename || 'upload.png',
            length: blob.size
        });
        if (!step1.ok) throw new Error('getUploadURLExternal: ' + (step1.error || 'unknown'));
        // Step 2: PUT bytes
        await _slackPutBytes(step1.upload_url, blob);
        // Step 3: completeUploadExternal — also posts the message with initial_comment
        var step3 = await slackAPI('files.completeUploadExternal', {
            files: [{ id: step1.file_id, title: title || filename || 'upload.png' }],
            channel_id: channelId,
            initial_comment: initialComment || ''
        });
        if (!step3.ok) throw new Error('completeUploadExternal: ' + (step3.error || 'unknown'));
        return step3;
    }

    // ── User Resolution ────────────────────────────────────────────
    // Slack IDs are managed in the Site Personnel panel — each tracked person has a
    // `.slackId` field. We resolve through `lib.trackedPersonnel.allPeople(site)` so
    // edits in the Personnel panel are picked up immediately (no sync lag).
    function _currentSite() {
        try {
            var s = lib.state && lib.state.settings && lib.state.settings.siteCode;
            return s ? s.toUpperCase() : '';
        } catch (e) { return ''; }
    }
    function _lookupSlackIdInPersonnel(alias) {
        if (!alias) return null;
        var aliasLower = alias.toLowerCase();
        try {
            var site = _currentSite();
            // Tracked list is the only collection that carries slackId per-person.
            // (allPeople() merges org-chart + custom records — neither has slackId.)
            if (site && lib.trackedPersonnel && lib.trackedPersonnel.get) {
                var tracked = lib.trackedPersonnel.get(site) || [];
                for (var i = 0; i < tracked.length; i++) {
                    if (tracked[i].alias && tracked[i].alias.toLowerCase() === aliasLower && tracked[i].slackId) {
                        return tracked[i].slackId;
                    }
                }
            }
            // Persistent library — survives untrack/retrack and works site-independently.
            if (lib.trackedPersonnel && lib.trackedPersonnel.getSlackLibrary) {
                var lib1 = lib.trackedPersonnel.getSlackLibrary();
                if (lib1 && lib1[aliasLower]) return lib1[aliasLower];
            }
        } catch (e) {}
        return null;
    }
    function hasSlackId(alias) { return !!_lookupSlackIdInPersonnel(alias); }
    function resolveSlackUserId(alias, mapKey) {
        var id = _lookupSlackIdInPersonnel(alias);
        if (id) return id;
        // Legacy fallback — pick up any pre-existing ASR map entries during transition
        var settings = getSettings();
        var legacy = ((mapKey === 'rbi' ? settings.rbiUserMap : settings.userMap) || {});
        var fb = legacy[(alias || '').toLowerCase()];
        if (fb) return fb;
        throw new Error('No Slack ID for "' + alias + '". Edit it in the Site Personnel panel (right sidebar).');
    }
    function resolveCCUserIds(settings, mapKey) {
        var ids = [];
        if (settings.myAlias) { try { ids.push(resolveSlackUserId(settings.myAlias, mapKey)); } catch (e) { console.warn('[ASR]', e.message); } }
        if (settings.ccAliases) {
            settings.ccAliases.split(',').map(function (a) { return a.trim(); }).filter(Boolean).forEach(function (alias) {
                try { ids.push(resolveSlackUserId(alias, mapKey)); } catch (e) { console.warn('[ASR]', e.message); }
            });
        }
        var unique = []; ids.forEach(function (id) { if (unique.indexOf(id) === -1) unique.push(id); });
        return unique;
    }

    // ── Task Scraping ──────────────────────────────────────────────
    function detectCalendarView() {
        var input = document.querySelector(CFG.SEL.VIEW_SELECTOR);
        if (!input) return null;
        var val = input.value.toLowerCase().trim();
        return ['day','week','month'].indexOf(val) !== -1 ? val : null;
    }
    function getCalendarDateText() {
        var cal = document.querySelector(CFG.SEL.CALENDAR);
        var p = cal ? cal.querySelector('p.MuiTypography-body1') : null;
        return p ? (p.textContent || '').trim() || 'Today' : 'Today';
    }
    function findTodaySlot() {
        var chip = document.querySelector(CFG.SEL.TODAY_WEEK);
        if (chip) return chip.closest(CFG.SEL.DAY_SLOT);
        chip = document.querySelector(CFG.SEL.TODAY_MONTH);
        if (chip) return chip.closest(CFG.SEL.DAY_SLOT);
        return null;
    }
    // Task ID extraction — order matters. Austin renders an anchor inside
    // every card pointing at `/tasks/task/{id}`; that anchor's UUID is the
    // authoritative ID the Task List page routes to. `card.id` is only
    // usable as a fallback and is often a React-internal id (or missing
    // entirely). PRIOR BEHAVIOR generated `crypto.randomUUID()` when both
    // were missing → guaranteed 404 in the DM. NEW: return null and let
    // the caller filter that row out. Silent 404s from a bad ID are
    // worse than an omitted row.
    var _TASK_ID_RE = /\/tasks\/task\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i;
    var _UUID_RE    = /([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i;
    var _UUID_STRICT_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

    // Task ID extraction. Austin's day-view cards don't always expose an
    // `<a href="/tasks/task/…">` anchor — sometimes the whole card is a
    // click target with the ID buried in a React handler. To handle both
    // shapes without generating fake UUIDs (the 19.57 fix), we search:
    //   1. Card + descendant anchors whose href matches /tasks/task/{uuid}
    //   2. The card's own id if it's a bare UUID
    //   3. Any descendant href containing a UUID (any URL shape)
    //   4. Any descendant data-* attribute matching a bare UUID
    //   5. Any descendant id whose value is a bare UUID
    // If none of these hit, return null → row is skipped, no fake IDs.
    function extractTaskId(card) {
        if (!card) return null;

        // 1. Preferred: anchor with /tasks/task/{uuid}
        var anchors = card.querySelectorAll('a[href*="/tasks/task/"]');
        for (var i = 0; i < anchors.length; i++) {
            var href = anchors[i].getAttribute('href') || '';
            var m = href.match(_TASK_ID_RE);
            if (m && m[1]) return m[1];
        }

        // 2. card.id itself
        if (_UUID_STRICT_RE.test(card.id || '')) return card.id;

        // 3. Any descendant href with a UUID (some deep-links live on
        //    action buttons, kebab menus, or nested anchors)
        var anyAnchor = card.querySelectorAll('a[href]');
        for (var j = 0; j < anyAnchor.length; j++) {
            var h = anyAnchor[j].getAttribute('href') || '';
            var mm = h.match(_UUID_RE);
            if (mm && mm[1]) return mm[1];
        }

        // 4. Any descendant data-* attribute whose value is a bare UUID
        //    (React sometimes stamps the task ID as data-testid="TaskCard-{uuid}"
        //    or similar — we extract the UUID from anywhere in the attr value)
        var withDataAttrs = card.querySelectorAll('*');
        for (var k = 0; k < withDataAttrs.length; k++) {
            var el = withDataAttrs[k];
            if (!el.attributes) continue;
            for (var a = 0; a < el.attributes.length; a++) {
                var attr = el.attributes[a];
                if (attr.name.indexOf('data-') !== 0) continue;
                var mv = String(attr.value || '').match(_UUID_RE);
                if (mv && mv[1]) return mv[1];
            }
            // Also check el.id
            if (_UUID_STRICT_RE.test(el.id || '')) return el.id;
        }

        return null;
    }

    // How many card rows the last scrape skipped because we couldn't
    // extract a real task ID from either the anchor or card.id. Surfaced
    // in the preview modal so users know why counts don't match.
    //
    // NOTE: this counter is READ from the ASR Part 2 IIFE below, which
    // has its own scope. `var _lastSkippedNoId` here is only visible to
    // Part 1 — so we mirror it onto `lib.asr._lastSkippedNoId` and
    // Part 2 accesses via the shared namespace (A._lastSkippedNoId).
    // Fixes "ReferenceError: _lastSkippedNoId is not defined" that
    // fired every time Part 2's showTaskPreviewModal opened.
    var _lastSkippedNoId = 0;

    function scrapeSmallCards(container, dateText) {
        var tasks = [];
        _lastSkippedNoId = 0;
        container.querySelectorAll(CFG.SEL.TASK_CARD).forEach(function (card) {
            var id = extractTaskId(card);
            var nameEl = card.querySelector(CFG.SEL.TASK_NAME_SMALL);
            var name = nameEl ? (nameEl.textContent || '').trim() : '';
            if (!name) return;
            if (!id) { _lastSkippedNoId++; return; }   // was: invent a UUID and 404 later
            var assigneeEl = card.querySelector(CFG.SEL.ASSIGNEE_SMALL);
            var assignee = assigneeEl ? (assigneeEl.textContent || '').trim() : '';
            tasks.push({ id: id, name: name, status: 'Unknown', type: '', assignee: assignee, site: '', isGroup: false, dateText: dateText });
        });
        return tasks;
    }
    function scrapeLargeCards(container, dateText) {
        var tasks = [];
        _lastSkippedNoId = 0;
        container.querySelectorAll(CFG.SEL.TASK_CARD).forEach(function (card) {
            var id = extractTaskId(card);
            var nameEl = card.querySelector(CFG.SEL.TASK_NAME_LARGE);
            var name = nameEl ? (nameEl.textContent || '').trim() : '';
            if (!name) return;
            if (!id) { _lastSkippedNoId++; return; }
            var assigneeEl = card.querySelector(CFG.SEL.ASSIGNEE_LARGE);
            var assignee = assigneeEl ? (assigneeEl.textContent || '').trim() : '';
            var statusEl = card.querySelector(CFG.SEL.STATUS_LABEL);
            var status = statusEl ? (statusEl.textContent || '').trim() : 'Unknown';
            var siteEl = card.querySelector(CFG.SEL.SITE_CHIP);
            var site = siteEl ? (siteEl.textContent || '').trim() : '';
            var type = '';
            card.querySelectorAll(CFG.SEL.DETAILS_LABEL).forEach(function (label) {
                if ((label.textContent || '').trim() === 'Task type') {
                    var sec = label.closest('section');
                    var desc = sec ? sec.querySelector(CFG.SEL.DETAILS_DESC) : null;
                    if (desc) type = (desc.textContent || '').trim();
                }
            });
            tasks.push({ id: id, name: name, status: status, type: type, assignee: assignee, site: site, isGroup: false, dateText: dateText });
        });
        return tasks;
    }
    async function expandAllRows(container) {
        var sel = container.querySelector(CFG.SEL.PAGINATION_SELECT);
        if (!sel) return;
        var rowsEl = container.querySelector(CFG.SEL.PAGINATION_ROWS);
        var txt = rowsEl ? (rowsEl.textContent || '') : '';
        var m = txt.match(/\d+[\u2013-](\d+)\s+of\s+(\d+)/);
        if (m && m[1] === m[2]) return;
        sel.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
        await sleep(300);
        var lb = document.querySelector('[role="listbox"]');
        if (!lb) { sel.click(); await sleep(400); lb = document.querySelector('[role="listbox"]'); }
        if (lb) {
            var opts = Array.from(lb.querySelectorAll('[role="option"]'));
            opts.sort(function (a, b) { return parseInt(b.textContent) - parseInt(a.textContent); });
            if (opts[0]) opts[0].click();
        }
        await sleep(600);
        try { await waitFor(function () {
            var el = container.querySelector(CFG.SEL.PAGINATION_ROWS);
            var t = el ? (el.textContent || '') : '';
            var x = t.match(/\d+[\u2013-](\d+)\s+of\s+(\d+)/); return x && x[1] === x[2];
        }, 5000); } catch (e) {}
    }
    function scrapeTasksFromDialog(dialogEl) {
        var tasks = [];
        _lastSkippedNoId = 0;
        var dateEl = dialogEl.querySelector(CFG.SEL.DATE_DISPLAY);
        var dateText = dateEl ? (dateEl.textContent || '').trim() : 'Today';
        dialogEl.querySelectorAll(CFG.SEL.TASK_CARD).forEach(function (card) {
            var id = extractTaskId(card);
            var nameEl = card.querySelector(CFG.SEL.TASK_NAME_MEDIUM);
            var name = nameEl ? (nameEl.textContent || '').trim() : 'Unknown Task';
            if (!id) { _lastSkippedNoId++; return; }
            var statusEl = card.querySelector(CFG.SEL.STATUS_LABEL);
            var status = statusEl ? (statusEl.textContent || '').trim() : 'Unknown';
            var typeEl = card.querySelector(CFG.SEL.TASK_TYPE_DIALOG);
            var type = typeEl ? (typeEl.textContent || '').trim() : '';
            var assigneeEl = card.querySelector(CFG.SEL.ASSIGNEE_SMALL);
            var assignee = assigneeEl ? (assigneeEl.textContent || '').trim() : '';
            var siteEl = card.querySelector(CFG.SEL.SITE_DIALOG);
            var site = siteEl ? (siteEl.textContent || '').trim() : '';
            var ac = assigneeEl ? assigneeEl.closest('[data-testid="UserDisplaySmall"]') : null;
            var isGroup = ac ? !!ac.querySelector(CFG.SEL.GROUP_ICON) : false;
            tasks.push({ id: id, name: name, status: status, type: type, assignee: assignee, site: site, isGroup: isGroup, dateText: dateText });
        });
        return tasks;
    }
    // ── GraphQL task fetch (19.57) ─────────────────────────────────
    // Authoritative alternative to DOM scraping. Returns real Austin task
    // IDs (never inventing UUIDs), plus dueDate, status, namespace, group
    // assignment, and other fields the scraper can't see. Same shape as
    // the scraper output so it drops straight into the preview modal.
    //
    // Query mirrors what the reference safety-suite script uses. If Austin
    // changes the schema this'll surface as a GraphQL error the caller
    // handles — better than silent 404s.
    var TASKS_V2_QUERY = 'query getTasksV2($input: TaskSearchV2RequestInput!) {' +
        '  getTasksV2(input: $input) {' +
        '    buckets {' +
        '      date' +
        '      tasks {' +
        '        assignedTo assignedToGroup assignedToGroupName' +
        '        description dueDate entityType genericTaskRelation' +
        '        id name namespace status' +
        '        targetResource { action name resourceAttributes }' +
        '        version' +
        '      }' +
        '      totalCount' +
        '    }' +
        '    count' +
        '  }' +
        '}';

    // Fetch tasks due on `dateISO` (YYYY-MM-DD) or today by default.
    // Uses the shared graphql wrapper — same auth + retry as every other
    // Austin query. Returns Promise<Array<taskLike>> in the scraper shape.
    function fetchTasksV2(dateISO) {
        if (!lib.graphql || !lib.graphql.executeWithRetry) {
            return Promise.reject(new Error('lib.graphql not available'));
        }
        var scopeId = (lib.auth && lib.auth.getScopeId) ? lib.auth.getScopeId() : null;
        if (!scopeId) return Promise.reject(new Error('No site scope — set your site code in WHS Settings.'));

        // Date window: 04:00 UTC on target date → 03:59:59 UTC next day
        // (matches Austin's Eastern-time bucketing). Format: YYYY-MM-DD.
        function _todayISO() {
            var d = new Date();
            return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
        }
        var target = dateISO || _todayISO();
        var nextDay = new Date(target + 'T12:00:00');
        nextDay.setDate(nextDay.getDate() + 1);
        var nextISO = nextDay.getFullYear() + '-' + String(nextDay.getMonth() + 1).padStart(2, '0') + '-' + String(nextDay.getDate()).padStart(2, '0');

        var variables = {
            input: {
                assignedToSites: [scopeId],
                siteIds: [scopeId],
                minimumDueDate: target + 'T04:00:00.000Z',
                maximumDueDate: nextISO + 'T03:59:59.999Z',
                statuses: ['OPEN', 'ASSIGNED'],
                tasksPerDay: 500,
                timeZone: 'America/New_York',
                pageInfoFrom: 0,
                pageInfoSize: 500
            }
        };
        return lib.graphql.executeWithRetry(TASKS_V2_QUERY, variables).then(function (data) {
            var buckets = (data && data.getTasksV2 && data.getTasksV2.buckets) || [];
            var raw = buckets.reduce(function (acc, b) { return acc.concat(b.tasks || []); }, []);
            // Reshape to the scraper contract so showTaskPreviewModal accepts it.
            return raw.filter(function (t) { return t && t.id; }).map(function (t) {
                var isGroup = !t.assignedTo && !!t.assignedToGroupName;
                return {
                    id:        t.id,
                    name:      t.name || 'Unnamed Task',
                    status:    t.status || 'Unknown',
                    type:      t.namespace || '',
                    assignee:  t.assignedTo || t.assignedToGroupName || '',
                    site:      '',
                    isGroup:   isGroup,
                    dueDate:   t.dueDate || null,
                    namespace: t.namespace || '',
                    dateText:  target
                };
            });
        });
    }

    async function collectTasks(source) {
        var dateText = getCalendarDateText();
        if (source === 'dialog') {
            var dialog = document.querySelector(CFG.SEL.DIALOG);
            if (!dialog) throw new Error('Dialog not found');
            await expandAllRows(dialog); await sleep(400);
            var dEl = dialog.querySelector(CFG.SEL.DATE_DISPLAY);
            return { tasks: scrapeTasksFromDialog(dialog), dateText: dEl ? (dEl.textContent || '').trim() || dateText : dateText };
        }
        if (source === 'day') {
            var cal = document.querySelector(CFG.SEL.CALENDAR);
            if (!cal) throw new Error('Calendar not found');
            await expandAllRows(cal); await sleep(400);
            // Austin swaps between LARGE and SMALL card variants on the day
            // view based on how many tasks are visible — around 5 tasks it
            // switches to the more-compact small cards which use a different
            // `data-testid`. `scrapeLargeCards` returned 0 in that case,
            // making the preview modal never open. Try large first; if it
            // finds nothing, fall back to small so both card densities work.
            var dayTasks = scrapeLargeCards(cal, dateText);
            if (dayTasks.length === 0) dayTasks = scrapeSmallCards(cal, dateText);
            return { tasks: dayTasks, dateText: dateText };
        }
        if (source === 'week' || source === 'month') {
            var slot = findTodaySlot();
            if (!slot) throw new Error('Could not find today\'s slot in ' + source + ' view.');
            var moreBtn = slot.querySelector(CFG.SEL.MORE_TASKS);
            if (moreBtn) {
                moreBtn.click(); await sleep(600);
                var dlg = await waitFor(function () {
                    var d = document.querySelector(CFG.SEL.DIALOG);
                    return d && d.querySelector(CFG.SEL.TASK_CARD) ? d : null;
                }, 5000);
                await expandAllRows(dlg); await sleep(400);
                var dlgDate = dlg.querySelector(CFG.SEL.DATE_DISPLAY);
                return { tasks: scrapeTasksFromDialog(dlg), dateText: dlgDate ? (dlgDate.textContent || '').trim() || dateText : dateText };
            }
            return { tasks: scrapeSmallCards(slot, dateText), dateText: dateText };
        }
        throw new Error('Unknown source: ' + source);
    }

    // ── Message Builders ───────────────────────────────────────────
    function buildTaskMessage(tasks, linkTemplate) {
        if (tasks.length === 1) {
            var t = tasks[0]; var link = linkTemplate.replace('{id}', t.id);
            return '\uD83D\uDD14 Reminder: Tasks Due Today in Austin \u2014 *' + t.name + '* \u2014 <' + link + '|Open in Austin>';
        }
        var msg = '\uD83D\uDD14 *Reminder: Tasks Due Today in Austin*\n';
        tasks.forEach(function (t) { var link = linkTemplate.replace('{id}', t.id); msg += '\n\u2022 *' + t.name + '* \u2014 <' + link + '|Open in Austin>'; });
        return msg;
    }

    function buildRBIMessage(pr, weekLabel) {
        var quota = pr.rbiQuota;
        var completed = pr.rbiTotal;
        var compliant = pr.rbiCompliant;
        var nonCompliant = pr.rbiNonCompliant;
        var remaining = Math.max(0, quota - compliant);
        var msg = '\uD83D\uDD0D *RBI Weekly Reminder \u2014 ' + weekLabel + '*\n\n';
        if (compliant >= quota) {
            msg += '\u2705 All RBIs complete! ' + compliant + '/' + quota + ' with findings. Great work!\n';
            if (nonCompliant > 0) msg += '\n\u26A0\uFE0F Note: ' + nonCompliant + ' RBI' + (nonCompliant > 1 ? 's' : '') + ' completed with 0 findings \u2014 these don\'t count toward your quota.';
            return msg;
        }
        if (completed === 0) {
            msg += '\uD83D\uDCCA Progress: *0/' + quota + '* RBIs completed\n';
            msg += '\n\u2757 *' + quota + ' RBI' + (quota > 1 ? 's' : '') + ' with at least 1 finding each* needed by end of week.\n';
            msg += '\nPlease complete your RBIs as soon as possible.';
            return msg;
        }
        msg += '\uD83D\uDCCA Progress: *' + compliant + '/' + quota + '* compliant RBIs\n';
        if (compliant > 0) msg += '\n\u2705 ' + compliant + ' RBI' + (compliant > 1 ? 's' : '') + ' completed with findings';
        if (nonCompliant > 0) msg += '\n\u26A0\uFE0F ' + nonCompliant + ' RBI' + (nonCompliant > 1 ? 's' : '') + ' completed with *0 findings* \u2014 findings are required for these to count';
        msg += '\n\n\u2757 Please complete *' + remaining + ' more RBI' + (remaining > 1 ? 's' : '') + '* with at least 1 finding ' + (remaining > 1 ? 'each ' : '') + 'before EOW.';
        return msg;
    }

