            '.we-heat-legend{display:flex;align-items:center;gap:6px;justify-content:center;font-size:10px;color:#888;margin-top:8px}',
            '.we-heat-legend-bar{width:100px;height:10px;background:linear-gradient(90deg,rgba(255,152,0,0.1),rgba(255,152,0,0.8));border-radius:2px;border:1px solid #21262d}',
            // ── Keyword cloud ──
            '.we-kw-hint{font-size:10px;color:#888;margin-bottom:8px;font-style:italic}',
