            '.we-kw-clear{background:transparent;border:1px solid #ffb74d;color:#ffb74d;padding:2px 8px;border-radius:3px;font-size:10px;cursor:pointer;font-family:inherit}',
            '.we-kw-clear:hover{background:#ffb74d;color:#232f3e}',
